var information_content_default={"guides":{"join":{"ru":{"title":"\u0412\u0430\u0448\u0430 \u043F\u0435\u0440\u0432\u0430\u044F \u0433\u043E\u043D\u043A\u0430 \u0441 ASG Racing","intro":"\u041D\u0430\u0447\u043D\u0438\u0442\u0435 \u0441 \u043F\u0443\u0431\u043B\u0438\u0447\u043D\u043E\u0433\u043E \u0441\u0435\u0440\u0432\u0435\u0440\u0430 \u0438\u043B\u0438 \u0432\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u0441\u043E\u0431\u044B\u0442\u0438\u0435 \u043F\u043E \u0440\u0430\u0441\u043F\u0438\u0441\u0430\u043D\u0438\u044E. \u041F\u0435\u0440\u0435\u0434 \u0441\u0442\u0430\u0440\u0442\u043E\u043C \u043F\u0440\u043E\u0432\u0435\u0440\u044C\u0442\u0435 \u0443\u0441\u043B\u043E\u0432\u0438\u044F \u0438\u043C\u0435\u043D\u043D\u043E \u0432\u0430\u0448\u0435\u0439 \u0433\u043E\u043D\u043A\u0438.","sections":[{"title":"\u0412\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u0433\u043E\u043D\u043A\u0443","html":"<p>\u041E\u0442\u043A\u0440\u043E\u0439\u0442\u0435 \u0440\u0430\u0441\u043F\u0438\u0441\u0430\u043D\u0438\u0435 \u0438 \u043F\u0440\u043E\u0432\u0435\u0440\u044C\u0442\u0435 \u0442\u0440\u0430\u0441\u0441\u0443, \u0434\u043E\u043F\u0443\u0441\u0442\u0438\u043C\u044B\u0435 \u043C\u0430\u0448\u0438\u043D\u044B, \u0432\u0440\u0435\u043C\u044F \u0441\u0442\u0430\u0440\u0442\u0430 \u0441 \u0447\u0430\u0441\u043E\u0432\u044B\u043C \u043F\u043E\u044F\u0441\u043E\u043C \u0438 \u0444\u043E\u0440\u043C\u0430\u0442. \u0423\u0431\u0435\u0434\u0438\u0442\u0435\u0441\u044C, \u0447\u0442\u043E \u0443 \u0432\u0430\u0441 \u0435\u0441\u0442\u044C \u043D\u0435\u043E\u0431\u0445\u043E\u0434\u0438\u043C\u044B\u0439 \u0438\u0433\u0440\u043E\u0432\u043E\u0439 \u043A\u043E\u043D\u0442\u0435\u043D\u0442 \u0434\u043B\u044F \u0432\u044B\u0431\u0440\u0430\u043D\u043D\u044B\u0445 \u0442\u0440\u0430\u0441\u0441\u044B \u0438 \u043C\u0430\u0448\u0438\u043D\u044B.</p>"},{"title":"\u041D\u0430\u0439\u0434\u0438\u0442\u0435 \u0441\u0435\u0440\u0432\u0435\u0440 \u0432 ACC","html":"<p>\u041E\u0442\u043A\u0440\u043E\u0439\u0442\u0435 \u0441\u043F\u0438\u0441\u043E\u043A \u0441\u0435\u0442\u0435\u0432\u044B\u0445 \u0441\u0435\u0440\u0432\u0435\u0440\u043E\u0432 Assetto Corsa Competizione \u0438 \u043D\u0430\u0439\u0434\u0438\u0442\u0435 ASG Racing. \u0414\u043B\u044F \u043E\u0440\u0433\u0430\u043D\u0438\u0437\u043E\u0432\u0430\u043D\u043D\u043E\u0433\u043E \u0441\u043E\u0431\u044B\u0442\u0438\u044F \u0441\u043B\u0435\u0434\u0443\u0439\u0442\u0435 \u0443\u043A\u0430\u0437\u0430\u043D\u0438\u044F\u043C \u043E \u0441\u0435\u0440\u0432\u0435\u0440\u0435 \u0438 \u0443\u0447\u0430\u0441\u0442\u0438\u0438 \u0432 \u0435\u0433\u043E \u043A\u0430\u0440\u0442\u043E\u0447\u043A\u0435.</p>"},{"title":"\u0418\u0437\u0443\u0447\u0438\u0442\u0435 \u043F\u0440\u0430\u0432\u0438\u043B\u0430 \u0438 \u043F\u043E\u0434\u0433\u043E\u0442\u043E\u0432\u044C\u0442\u0435\u0441\u044C","html":"<p>\u041F\u0435\u0440\u0435\u0434 \u0441\u0442\u0430\u0440\u0442\u043E\u043C \u043E\u0437\u043D\u0430\u043A\u043E\u043C\u044C\u0442\u0435\u0441\u044C \u0441 \u0433\u043E\u043D\u043E\u0447\u043D\u044B\u043C\u0438 \u043F\u0440\u0430\u0432\u0438\u043B\u0430\u043C\u0438 \u0438 \u0442\u0440\u0435\u0431\u043E\u0432\u0430\u043D\u0438\u044F\u043C\u0438 \u0434\u043E\u043F\u0443\u0441\u043A\u0430 \u0432\u044B\u0431\u0440\u0430\u043D\u043D\u043E\u0433\u043E \u0441\u043E\u0431\u044B\u0442\u0438\u044F. \u0422\u0440\u0435\u043D\u0438\u0440\u0443\u0439\u0442\u0435\u0441\u044C \u0431\u0435\u0437\u043E\u043F\u0430\u0441\u043D\u043E \u0438 \u0443\u0432\u0430\u0436\u0430\u0439\u0442\u0435 \u0434\u0440\u0443\u0433\u0438\u0445 \u043F\u0438\u043B\u043E\u0442\u043E\u0432. \u0421\u043E\u0431\u0441\u0442\u0432\u0435\u043D\u043D\u044B\u0439 Safety Rating ASG Racing \u043E\u0442\u043B\u0438\u0447\u0430\u0435\u0442\u0441\u044F \u043E\u0442 \u0432\u043D\u0443\u0442\u0440\u0438\u0438\u0433\u0440\u043E\u0432\u043E\u0433\u043E SA.</p>"},{"title":"\u041E\u0441\u0442\u0430\u0432\u0430\u0439\u0442\u0435\u0441\u044C \u0432 \u0441\u043E\u043E\u0431\u0449\u0435\u0441\u0442\u0432\u0435","html":"<p>\u0421\u043B\u0435\u0434\u0438\u0442\u0435 \u0437\u0430 \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442\u0430\u043C\u0438, \u0437\u043D\u0430\u043A\u043E\u043C\u044C\u0442\u0435\u0441\u044C \u0441 \u043A\u043B\u0443\u0431\u0430\u043C\u0438 \u0438 \u043A\u043E\u043C\u0430\u043D\u0434\u0430\u043C\u0438. \u0412 \u043A\u0430\u043D\u0430\u043B\u0430\u0445 \u0441\u043E\u043E\u0431\u0449\u0435\u0441\u0442\u0432\u0430, \u0441\u0441\u044B\u043B\u043A\u0438 \u043D\u0430 \u043A\u043E\u0442\u043E\u0440\u044B\u0435 \u0435\u0441\u0442\u044C \u043D\u0430 \u0433\u043B\u0430\u0432\u043D\u043E\u0439, \u043C\u043E\u0436\u043D\u043E \u0441\u043B\u0435\u0434\u0438\u0442\u044C \u0437\u0430 \u0430\u043D\u043E\u043D\u0441\u0430\u043C\u0438 \u0438 \u043E\u0431\u0449\u0430\u0442\u044C\u0441\u044F \u0441 \u0434\u0440\u0443\u0433\u0438\u043C\u0438 \u043F\u0438\u043B\u043E\u0442\u0430\u043C\u0438.</p>"}],"source":"/ru/join/"},"en":{"title":"Your first race with ASG Racing","intro":"Start with a public server or choose a scheduled event. Check the requirements for your chosen race before joining.","sections":[{"title":"Choose your race","html":"<p>Open the schedule and check the track, eligible cars, start time with its time zone and race format. Make sure you have the required game content for that track and car.</p>"},{"title":"Find the server in ACC","html":"<p>Open the Assetto Corsa Competizione multiplayer server browser and search for ASG Racing. For an organised event, follow the server and participation instructions shown in its details.</p>"},{"title":"Read the rules and prepare","html":"<p>Review the racing rules before starting. Check any entry requirements for the selected event, practise safely and respect other drivers. ASG Racing's own Safety Rating is distinct from the game's SA.</p>"},{"title":"Stay involved","html":"<p>Follow your results and explore clubs and teams. The community channels linked from the main page offer announcements and opportunities to talk with other drivers.</p>"}],"source":"/join/"}},"about":{"ru":{"title":"ASG Racing \u2014 \u0433\u043E\u043D\u043E\u0447\u043D\u043E\u0435 \u0441\u043E\u043E\u0431\u0449\u0435\u0441\u0442\u0432\u043E ACC","intro":"ASG Racing \u043E\u0431\u044A\u0435\u0434\u0438\u043D\u044F\u0435\u0442 \u043F\u0438\u043B\u043E\u0442\u043E\u0432 \u0432\u043E\u043A\u0440\u0443\u0433 \u0433\u043E\u043D\u043E\u043A \u0438 \u0441\u043E\u0432\u043C\u0435\u0441\u0442\u043D\u043E\u0433\u043E \u0440\u0430\u0437\u0432\u0438\u0442\u0438\u044F \u0432 Assetto Corsa Competizione.","sections":[{"title":"\u0413\u043E\u043D\u043A\u0438 \u0438 \u0447\u0435\u043C\u043F\u0438\u043E\u043D\u0430\u0442\u044B","html":"<p>\u041F\u0443\u0431\u043B\u0438\u0447\u043D\u044B\u0435 \u0441\u0435\u0440\u0432\u0435\u0440\u044B \u043F\u043E\u0437\u0432\u043E\u043B\u044F\u044E\u0442 \u0433\u043E\u043D\u044F\u0442\u044C \u0432\u043C\u0435\u0441\u0442\u0435 \u0441 \u0434\u0440\u0443\u0433\u0438\u043C\u0438 \u0443\u0447\u0430\u0441\u0442\u043D\u0438\u043A\u0430\u043C\u0438. \u0421\u043E\u0431\u044B\u0442\u0438\u044F \u043F\u043E \u0440\u0430\u0441\u043F\u0438\u0441\u0430\u043D\u0438\u044E \u0438 \u0447\u0435\u043C\u043F\u0438\u043E\u043D\u0430\u0442\u044B \u043E\u0431\u044A\u0435\u0434\u0438\u043D\u044F\u044E\u0442 \u043F\u0438\u043B\u043E\u0442\u043E\u0432 \u0432\u043E\u043A\u0440\u0443\u0433 \u043E\u043F\u0440\u0435\u0434\u0435\u043B\u0451\u043D\u043D\u044B\u0445 \u0433\u043E\u043D\u043E\u0447\u043D\u044B\u0445 \u0444\u043E\u0440\u043C\u0430\u0442\u043E\u0432. \u0410\u043A\u0442\u0443\u0430\u043B\u044C\u043D\u044B\u0435 \u0443\u0441\u043B\u043E\u0432\u0438\u044F \u0443\u0447\u0430\u0441\u0442\u0438\u044F \u0443\u043A\u0430\u0437\u0430\u043D\u044B \u043D\u0430 \u0441\u0442\u0440\u0430\u043D\u0438\u0446\u0430\u0445 \u0441\u043E\u0431\u044B\u0442\u0438\u0439.</p>"},{"title":"\u041A\u043B\u0443\u0431\u044B \u0438 \u043A\u043E\u043C\u0430\u043D\u0434\u044B","html":"<p>\u041F\u043E\u0440\u0442\u0430\u043B \u043E\u0431\u044A\u0435\u0434\u0438\u043D\u044F\u0435\u0442 \u0440\u0430\u0437\u043D\u044B\u0435 \u043A\u043B\u0443\u0431\u044B \u0438 \u043A\u043E\u043C\u0430\u043D\u0434\u044B \u0441 \u0441\u043E\u0431\u0441\u0442\u0432\u0435\u043D\u043D\u044B\u043C\u0438 \u043F\u0440\u043E\u0444\u0438\u043B\u044F\u043C\u0438, \u0441\u043E\u0441\u0442\u0430\u0432\u0430\u043C\u0438 \u0438 \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442\u0430\u043C\u0438. ASG Racing \u2014 \u043E\u0431\u0449\u0435\u0435 \u0441\u043E\u043E\u0431\u0449\u0435\u0441\u0442\u0432\u043E, \u0430 \u0443 \u043A\u0430\u0436\u0434\u043E\u0439 \u043A\u043E\u043C\u0430\u043D\u0434\u044B \u0441\u0432\u043E\u0438 \u0443\u0447\u0430\u0441\u0442\u043D\u0438\u043A\u0438 \u0438 \u0443\u0441\u043B\u043E\u0432\u0438\u044F \u0432\u0441\u0442\u0443\u043F\u043B\u0435\u043D\u0438\u044F.</p>"},{"title":"\u0420\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442\u044B \u0438 \u0440\u0430\u0437\u0432\u0438\u0442\u0438\u0435","html":"<p>\u0420\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442\u044B \u043F\u0438\u043B\u043E\u0442\u043E\u0432 \u0438 \u0440\u0435\u0439\u0442\u0438\u043D\u0433\u0438 \u043F\u043E\u043C\u043E\u0433\u0430\u044E\u0442 \u0441\u043B\u0435\u0434\u0438\u0442\u044C \u0437\u0430 \u043F\u0440\u043E\u0433\u0440\u0435\u0441\u0441\u043E\u043C. \u0418\u0441\u0442\u043E\u0440\u0438\u044F \u0433\u043E\u043D\u043E\u043A, \u043B\u0443\u0447\u0448\u0438\u0435 \u043A\u0440\u0443\u0433\u0438 \u0438 \u043F\u043E\u043A\u0430\u0437\u0430\u0442\u0435\u043B\u0438 \u0431\u0435\u0437\u043E\u043F\u0430\u0441\u043D\u043E\u0441\u0442\u0438 \u0434\u043E\u043F\u043E\u043B\u043D\u044F\u044E\u0442 \u0438\u0442\u043E\u0433 \u043E\u0442\u0434\u0435\u043B\u044C\u043D\u043E\u0433\u043E \u0444\u0438\u043D\u0438\u0448\u0430.</p>"},{"title":"\u041E\u0431\u0449\u0435\u043D\u0438\u0435","html":"<p>\u041D\u0430 \u0433\u043B\u0430\u0432\u043D\u043E\u0439 \u0441\u043E\u0431\u0440\u0430\u043D\u044B \u0441\u0441\u044B\u043B\u043A\u0438 \u043D\u0430 Telegram, Discord \u0438 \u043C\u0435\u0434\u0438\u0430\u043A\u0430\u043D\u0430\u043B\u044B \u0441\u043E\u043E\u0431\u0449\u0435\u0441\u0442\u0432\u0430. \u0414\u0435\u043B\u0438\u0442\u0435\u0441\u044C \u0432\u043F\u0435\u0447\u0430\u0442\u043B\u0435\u043D\u0438\u044F\u043C\u0438 \u043E\u0442 \u0433\u043E\u043D\u043E\u043A, \u0441\u043B\u0435\u0434\u0438\u0442\u0435 \u0437\u0430 \u0430\u043D\u043E\u043D\u0441\u0430\u043C\u0438 \u0438 \u0437\u043D\u0430\u043A\u043E\u043C\u044C\u0442\u0435\u0441\u044C \u0441 \u0434\u0440\u0443\u0433\u0438\u043C\u0438 \u043F\u0438\u043B\u043E\u0442\u0430\u043C\u0438.</p>"}],"source":"/ru/about/"},"en":{"title":"ASG Racing: an ACC racing community","intro":"ASG Racing connects drivers through racing and shared progress in Assetto Corsa Competizione.","sections":[{"title":"Races and championships","html":"<p>Public servers offer a place to drive with others. Scheduled events and championships bring drivers together around specific race formats. The event pages provide the current conditions for participation.</p>"},{"title":"Clubs and teams","html":"<p>The portal brings together different clubs and teams with their own profiles, rosters and results. ASG Racing is the wider community; each team has its own identity and membership arrangements.</p>"},{"title":"Results and progress","html":"<p>Driver results and standings help participants follow their progress. Race history, best laps and safety information provide context beyond a single finish.</p>"},{"title":"Communication","html":"<p>Visit the main page for the community's Telegram, Discord and media links. Share race experiences, follow announcements and meet other drivers.</p>"}],"source":"/about/"}}},"documents":{"privacy":{"title":"\u041F\u043E\u043B\u0438\u0442\u0438\u043A\u0430 \u0432 \u043E\u0442\u043D\u043E\u0448\u0435\u043D\u0438\u0438 \u043E\u0431\u0440\u0430\u0431\u043E\u0442\u043A\u0438 \u043F\u0435\u0440\u0441\u043E\u043D\u0430\u043B\u044C\u043D\u044B\u0445 \u0434\u0430\u043D\u043D\u044B\u0445","intro_html":'<header class="legal-header">\n      <div class="legal-kicker">ASG Racing</div>\n      <h2>\u041F\u043E\u043B\u0438\u0442\u0438\u043A\u0430 \u0432 \u043E\u0442\u043D\u043E\u0448\u0435\u043D\u0438\u0438 \u043E\u0431\u0440\u0430\u0431\u043E\u0442\u043A\u0438 \u043F\u0435\u0440\u0441\u043E\u043D\u0430\u043B\u044C\u043D\u044B\u0445 \u0434\u0430\u043D\u043D\u044B\u0445</h2>\n      <p class="legal-updated">\u0414\u0430\u0442\u0430 \u043E\u0431\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u044F: 30.04.2026</p>\n    </header>',"sections":[{"id":"section-1","title":"1. \u041E\u0431\u0449\u0438\u0435 \u043F\u043E\u043B\u043E\u0436\u0435\u043D\u0438\u044F","html":"<p>\n        \u041D\u0430\u0441\u0442\u043E\u044F\u0449\u0430\u044F \u043F\u043E\u043B\u0438\u0442\u0438\u043A\u0430 \u043E\u043F\u0440\u0435\u0434\u0435\u043B\u044F\u0435\u0442 \u043F\u043E\u0440\u044F\u0434\u043E\u043A \u043E\u0431\u0440\u0430\u0431\u043E\u0442\u043A\u0438 \u043F\u0435\u0440\u0441\u043E\u043D\u0430\u043B\u044C\u043D\u044B\u0445 \u0434\u0430\u043D\u043D\u044B\u0445 \u043F\u043E\u0441\u0435\u0442\u0438\u0442\u0435\u043B\u0435\u0439 \u0441\u0430\u0439\u0442\u0430 ASG Racing,\n        \u0432\u043A\u043B\u044E\u0447\u0430\u044F \u0441\u0442\u0440\u0430\u043D\u0438\u0446\u044B \u043F\u0440\u043E\u0435\u043A\u0442\u0430, \u0440\u0430\u0437\u043C\u0435\u0449\u0451\u043D\u043D\u044B\u0435 \u043F\u043E \u0430\u0434\u0440\u0435\u0441\u0430\u043C <code>https://asgracing.ru/</code>,\n        <code>https://asgracing.ru/hourly/</code>.\n      </p>\n      <p>\n        \u041F\u043E\u043B\u0438\u0442\u0438\u043A\u0430 \u043F\u043E\u0434\u0433\u043E\u0442\u043E\u0432\u043B\u0435\u043D\u0430 \u0432\u043E \u0438\u0441\u043F\u043E\u043B\u043D\u0435\u043D\u0438\u0435 \u0442\u0440\u0435\u0431\u043E\u0432\u0430\u043D\u0438\u0439 \u0424\u0435\u0434\u0435\u0440\u0430\u043B\u044C\u043D\u043E\u0433\u043E \u0437\u0430\u043A\u043E\u043D\u0430 \u043E\u0442 27.07.2006 \u2116 152-\u0424\u0417 \xAB\u041E\n        \u043F\u0435\u0440\u0441\u043E\u043D\u0430\u043B\u044C\u043D\u044B\u0445 \u0434\u0430\u043D\u043D\u044B\u0445\xBB, \u0432 \u0442\u043E\u043C \u0447\u0438\u0441\u043B\u0435 \u0441\u0442\u0430\u0442\u044C\u0438 18.1 \u0443\u043A\u0430\u0437\u0430\u043D\u043D\u043E\u0433\u043E \u0437\u0430\u043A\u043E\u043D\u0430.\n      </p>"},{"id":"section-2","title":"2. \u0421\u0432\u0435\u0434\u0435\u043D\u0438\u044F \u043E\u0431 \u043E\u043F\u0435\u0440\u0430\u0442\u043E\u0440\u0435","html":'<dl class="legal-definition-grid">\n        <div>\n          <dt>\u041E\u043F\u0435\u0440\u0430\u0442\u043E\u0440 \u043F\u0435\u0440\u0441\u043E\u043D\u0430\u043B\u044C\u043D\u044B\u0445 \u0434\u0430\u043D\u043D\u044B\u0445</dt>\n          <dd>\u041E\u043D\u043B\u0430\u0439\u043D \u0441\u043E\u043E\u0431\u0449\u0435\u0441\u0442\u0432\u043E ASG Racing</dd>\n        </div>\n        <div>\n          <dt>E-mail \u0434\u043B\u044F \u043E\u0431\u0440\u0430\u0449\u0435\u043D\u0438\u0439 \u043F\u043E \u043F\u0435\u0440\u0441\u043E\u043D\u0430\u043B\u044C\u043D\u044B\u043C \u0434\u0430\u043D\u043D\u044B\u043C</dt>\n          <dd>itriahon@gmail.com</dd>\n        </div>\n        <div>\n          <dt>\u041E\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u0435\u043D\u043D\u044B\u0439 \u0437\u0430 \u043E\u0440\u0433\u0430\u043D\u0438\u0437\u0430\u0446\u0438\u044E \u043E\u0431\u0440\u0430\u0431\u043E\u0442\u043A\u0438 \u043F\u0435\u0440\u0441\u043E\u043D\u0430\u043B\u044C\u043D\u044B\u0445 \u0434\u0430\u043D\u043D\u044B\u0445</dt>\n          <dd>\u041E\u0431\u0440\u0430\u0449\u0435\u043D\u0438\u044F \u043F\u043E \u0432\u043E\u043F\u0440\u043E\u0441\u0430\u043C \u043F\u0435\u0440\u0441\u043E\u043D\u0430\u043B\u044C\u043D\u044B\u0445 \u0434\u0430\u043D\u043D\u044B\u0445 \u043F\u0440\u0438\u043D\u0438\u043C\u0430\u0435\u0442 \u043E\u043F\u0435\u0440\u0430\u0442\u043E\u0440 \u043F\u043E \u0430\u0434\u0440\u0435\u0441\u0443: itriahon@gmail.com</dd>\n        </div>\n      </dl>'},{"id":"section-3","title":"3. \u041A\u0430\u0442\u0435\u0433\u043E\u0440\u0438\u0438 \u0441\u0443\u0431\u044A\u0435\u043A\u0442\u043E\u0432 \u0438 \u043E\u0431\u0440\u0430\u0431\u0430\u0442\u044B\u0432\u0430\u0435\u043C\u044B\u0445 \u0434\u0430\u043D\u043D\u044B\u0445","html":"<p>\u041E\u043F\u0435\u0440\u0430\u0442\u043E\u0440 \u043E\u0431\u0440\u0430\u0431\u0430\u0442\u044B\u0432\u0430\u0435\u0442 \u0434\u0430\u043D\u043D\u044B\u0435 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0438\u0445 \u043A\u0430\u0442\u0435\u0433\u043E\u0440\u0438\u0439 \u0441\u0443\u0431\u044A\u0435\u043A\u0442\u043E\u0432:</p>\n      <ul>\n        <li>\u043F\u043E\u0441\u0435\u0442\u0438\u0442\u0435\u043B\u0438 \u0441\u0430\u0439\u0442\u0430 \u0438 \u043E\u0442\u0434\u0435\u043B\u044C\u043D\u044B\u0445 \u0441\u0442\u0440\u0430\u043D\u0438\u0446 \u043F\u0440\u043E\u0435\u043A\u0442\u0430 ASG Racing;</li>\n        <li>\u0443\u0447\u0430\u0441\u0442\u043D\u0438\u043A\u0438 \u0433\u043E\u043D\u043E\u043A, \u0432\u043E\u0434\u0438\u0442\u0435\u043B\u0438 \u0438 \u0438\u043D\u044B\u0435 \u043B\u0438\u0446\u0430, \u0447\u044C\u0438 \u0434\u0430\u043D\u043D\u044B\u0435 \u0441\u043E\u0434\u0435\u0440\u0436\u0430\u0442\u0441\u044F \u0432 \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442\u0430\u0445 \u0437\u0430\u0435\u0437\u0434\u043E\u0432, \u0440\u0435\u0439\u0442\u0438\u043D\u0433\u0430\u0445, \u0430\u0440\u0445\u0438\u0432\u0430\u0445 \u0433\u043E\u043D\u043E\u043A \u0438 \u043F\u0443\u0431\u043B\u0438\u0447\u043D\u044B\u0445 \u043F\u0440\u043E\u0444\u0438\u043B\u044F\u0445 \u0443\u0447\u0430\u0441\u0442\u043D\u0438\u043A\u043E\u0432;</li>\n        <li>\u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u0435\u043B\u0438, \u0434\u043E\u0431\u0440\u043E\u0432\u043E\u043B\u044C\u043D\u043E \u0443\u0447\u0430\u0441\u0442\u0432\u0443\u044E\u0449\u0438\u0435 \u0432 \u0433\u043E\u043B\u043E\u0441\u043E\u0432\u0430\u043D\u0438\u0438 \u0437\u0430 \u0441\u043B\u043E\u0442 \u0447\u0430\u0441\u043E\u0432\u043E\u0439 \u0433\u043E\u043D\u043A\u0438;</li>\n        <li>\u043B\u0438\u0446\u0430, \u043D\u0430\u043F\u0440\u0430\u0432\u043B\u044F\u044E\u0449\u0438\u0435 \u043E\u043F\u0435\u0440\u0430\u0442\u043E\u0440\u0443 \u043E\u0431\u0440\u0430\u0449\u0435\u043D\u0438\u044F \u043F\u043E \u0432\u043E\u043F\u0440\u043E\u0441\u0430\u043C \u043E\u0431\u0440\u0430\u0431\u043E\u0442\u043A\u0438 \u043F\u0435\u0440\u0441\u043E\u043D\u0430\u043B\u044C\u043D\u044B\u0445 \u0434\u0430\u043D\u043D\u044B\u0445.</li>\n      </ul>\n      <p>\u041C\u043E\u0433\u0443\u0442 \u043E\u0431\u0440\u0430\u0431\u0430\u0442\u044B\u0432\u0430\u0442\u044C\u0441\u044F \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0438\u0435 \u0434\u0430\u043D\u043D\u044B\u0435:</p>\n      <ul>\n        <li>IP-\u0430\u0434\u0440\u0435\u0441, \u0441\u0432\u0435\u0434\u0435\u043D\u0438\u044F \u043E \u0431\u0440\u0430\u0443\u0437\u0435\u0440\u0435, \u044F\u0437\u044B\u043A\u0435 \u0438\u043D\u0442\u0435\u0440\u0444\u0435\u0439\u0441\u0430, \u0442\u0438\u043F\u0435 \u0443\u0441\u0442\u0440\u043E\u0439\u0441\u0442\u0432\u0430 \u0438 \u043E\u043F\u0435\u0440\u0430\u0446\u0438\u043E\u043D\u043D\u043E\u0439 \u0441\u0438\u0441\u0442\u0435\u043C\u0435;</li>\n        <li>\u0430\u0434\u0440\u0435\u0441\u0430 \u0437\u0430\u043F\u0440\u043E\u0448\u0435\u043D\u043D\u044B\u0445 \u0441\u0442\u0440\u0430\u043D\u0438\u0446, URL \u043F\u0435\u0440\u0435\u0445\u043E\u0434\u0430, \u0434\u0430\u0442\u0430 \u0438 \u0432\u0440\u0435\u043C\u044F \u043F\u043E\u0441\u0435\u0449\u0435\u043D\u0438\u044F, \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044F \u043D\u0430 \u0441\u0442\u0440\u0430\u043D\u0438\u0446\u0430\u0445;</li>\n        <li>\u0438\u0434\u0435\u043D\u0442\u0438\u0444\u0438\u043A\u0430\u0442\u043E\u0440\u044B cookie \u0438 localStorage, \u0432 \u0442\u043E\u043C \u0447\u0438\u0441\u043B\u0435 \u0438\u0434\u0435\u043D\u0442\u0438\u0444\u0438\u043A\u0430\u0442\u043E\u0440\u044B \u042F\u043D\u0434\u0435\u043A\u0441 \u041C\u0435\u0442\u0440\u0438\u043A\u0438;</li>\n        <li>\n          \u0432 \u043E\u0442\u043D\u043E\u0448\u0435\u043D\u0438\u0438 \u0443\u0447\u0430\u0441\u0442\u043D\u0438\u043A\u043E\u0432 \u0433\u043E\u043D\u043E\u043A \u0438 \u043F\u0443\u0431\u043B\u0438\u0447\u043D\u044B\u0445 \u043F\u0440\u043E\u0444\u0438\u043B\u0435\u0439: \u0438\u043C\u044F, \u0444\u0430\u043C\u0438\u043B\u0438\u044F, \u043D\u0438\u043A, shortName \u0438 \u0438\u043D\u044B\u0435 \u043E\u0431\u043E\u0437\u043D\u0430\u0447\u0435\u043D\u0438\u044F\n          \u0432\u043E\u0434\u0438\u0442\u0435\u043B\u044F, \u0435\u0441\u043B\u0438 \u043E\u043D\u0438 \u0441\u043E\u0434\u0435\u0440\u0436\u0430\u0442\u0441\u044F \u0432 \u0438\u0441\u0445\u043E\u0434\u043D\u044B\u0445 \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442\u0430\u0445; \u0438\u0434\u0435\u043D\u0442\u0438\u0444\u0438\u043A\u0430\u0442\u043E\u0440\u044B <code>player_id</code> \u0438\n          <code>public_id</code>; \u0441\u0432\u0435\u0434\u0435\u043D\u0438\u044F \u043E \u0437\u0430\u0435\u0437\u0434\u0430\u0445, \u043F\u043E\u0437\u0438\u0446\u0438\u044F\u0445, \u0441\u0442\u0430\u0440\u0442\u0430\u0445, \u0444\u0438\u043D\u0438\u0448\u0430\u0445, \u043A\u0440\u0443\u0433\u0430\u0445, \u043B\u0443\u0447\u0448\u0438\u0445 \u043A\u0440\u0443\u0433\u0430\u0445,\n          \u0448\u0442\u0440\u0430\u0444\u0430\u0445, \u043E\u0447\u043A\u0430\u0445, \u0440\u0435\u0439\u0442\u0438\u043D\u0433\u0430\u0445, \u0430\u0432\u0442\u043E\u043C\u043E\u0431\u0438\u043B\u044F\u0445, \u0442\u0440\u0430\u0441\u0441\u0430\u0445, \u0438\u0441\u0442\u043E\u0440\u0438\u0438 \u0443\u0447\u0430\u0441\u0442\u0438\u044F \u0438 \u043F\u0440\u043E\u0438\u0437\u0432\u043E\u0434\u043D\u044B\u0445 \u0441\u0442\u0430\u0442\u0438\u0441\u0442\u0438\u0447\u0435\u0441\u043A\u0438\u0445\n          \u043F\u043E\u043A\u0430\u0437\u0430\u0442\u0435\u043B\u044F\u0445;\n        </li>\n        <li>\n          \u043F\u0440\u0438 \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u043D\u0438\u0438 \u0433\u043E\u043B\u043E\u0441\u043E\u0432\u0430\u043D\u0438\u044F: \u0442\u0435\u0445\u043D\u0438\u0447\u0435\u0441\u043A\u0438\u0439 \u0438\u0434\u0435\u043D\u0442\u0438\u0444\u0438\u043A\u0430\u0442\u043E\u0440 \u0431\u0440\u0430\u0443\u0437\u0435\u0440\u0430 <code>hourlyVoteVoterId</code>,\n          \u0438\u0434\u0435\u043D\u0442\u0438\u0444\u0438\u043A\u0430\u0442\u043E\u0440 \u0441\u043E\u0431\u044B\u0442\u0438\u044F (\u0441\u043B\u043E\u0442\u0430), \u0441\u0442\u0430\u0442\u0443\u0441 \u0433\u043E\u043B\u043E\u0441\u0430 \u0438 \u0441\u0432\u044F\u0437\u0430\u043D\u043D\u0430\u044F \u0441\u043B\u0443\u0436\u0435\u0431\u043D\u0430\u044F \u0438\u043D\u0444\u043E\u0440\u043C\u0430\u0446\u0438\u044F.\n        </li>\n        <li>\n          \u043F\u0440\u0438 \u043E\u0431\u0440\u0430\u0449\u0435\u043D\u0438\u0438 \u0441\u0443\u0431\u044A\u0435\u043A\u0442\u0430 \u043F\u0435\u0440\u0441\u043E\u043D\u0430\u043B\u044C\u043D\u044B\u0445 \u0434\u0430\u043D\u043D\u044B\u0445: \u0438\u043C\u044F, \u0430\u0434\u0440\u0435\u0441 \u044D\u043B\u0435\u043A\u0442\u0440\u043E\u043D\u043D\u043E\u0439 \u043F\u043E\u0447\u0442\u044B \u0438 \u0438\u043D\u044B\u0435 \u0441\u0432\u0435\u0434\u0435\u043D\u0438\u044F, \u043A\u043E\u0442\u043E\u0440\u044B\u0435\n          \u0441\u0443\u0431\u044A\u0435\u043A\u0442 \u0434\u043E\u0431\u0440\u043E\u0432\u043E\u043B\u044C\u043D\u043E \u0443\u043A\u0430\u0436\u0435\u0442 \u0432 \u043E\u0431\u0440\u0430\u0449\u0435\u043D\u0438\u0438.\n        </li>\n      </ul>\n      <p>\n        \u0421\u0430\u0439\u0442 \u043D\u0435 \u043F\u0440\u0435\u0434\u043D\u0430\u0437\u043D\u0430\u0447\u0435\u043D \u0434\u043B\u044F \u0441\u043E\u0437\u043D\u0430\u0442\u0435\u043B\u044C\u043D\u043E\u0433\u043E \u0441\u0431\u043E\u0440\u0430 \u0441\u043F\u0435\u0446\u0438\u0430\u043B\u044C\u043D\u044B\u0445 \u043A\u0430\u0442\u0435\u0433\u043E\u0440\u0438\u0439 \u043F\u0435\u0440\u0441\u043E\u043D\u0430\u043B\u044C\u043D\u044B\u0445 \u0434\u0430\u043D\u043D\u044B\u0445 \u0438\n        \u0431\u0438\u043E\u043C\u0435\u0442\u0440\u0438\u0447\u0435\u0441\u043A\u0438\u0445 \u043F\u0435\u0440\u0441\u043E\u043D\u0430\u043B\u044C\u043D\u044B\u0445 \u0434\u0430\u043D\u043D\u044B\u0445.\n      </p>"},{"id":"section-4","title":"4. \u0418\u0441\u0442\u043E\u0447\u043D\u0438\u043A\u0438 \u043F\u043E\u043B\u0443\u0447\u0435\u043D\u0438\u044F \u0434\u0430\u043D\u043D\u044B\u0445","html":"<ul>\n        <li>\u043D\u0435\u043F\u043E\u0441\u0440\u0435\u0434\u0441\u0442\u0432\u0435\u043D\u043D\u043E \u043E\u0442 \u0443\u0441\u0442\u0440\u043E\u0439\u0441\u0442\u0432\u0430 \u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u0435\u043B\u044F \u043F\u0440\u0438 \u043F\u043E\u0441\u0435\u0449\u0435\u043D\u0438\u0438 \u0441\u0430\u0439\u0442\u0430 \u0438 \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u043D\u0438\u0438 \u0438\u043D\u0442\u0435\u0440\u0444\u0435\u0439\u0441\u0430 \u043F\u0440\u043E\u0435\u043A\u0442\u0430;</li>\n        <li>\u0438\u0437 \u042F\u043D\u0434\u0435\u043A\u0441 \u041C\u0435\u0442\u0440\u0438\u043A\u0438 \u043F\u043E\u0441\u043B\u0435 \u043F\u043E\u043B\u0443\u0447\u0435\u043D\u0438\u044F \u0441\u043E\u0433\u043B\u0430\u0441\u0438\u044F \u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u0435\u043B\u044F \u043D\u0430 \u0430\u043D\u0430\u043B\u0438\u0442\u0438\u0447\u0435\u0441\u043A\u0438\u0435 cookie \u0438 localStorage;</li>\n        <li>\u0438\u0437 \u0444\u0430\u0439\u043B\u043E\u0432 \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442\u043E\u0432 \u0433\u043E\u043D\u043E\u043A, \u043F\u0440\u043E\u0442\u043E\u043A\u043E\u043B\u043E\u0432 \u0437\u0430\u0435\u0437\u0434\u043E\u0432 \u0438 \u0438\u043D\u044B\u0445 \u0442\u0435\u0445\u043D\u0438\u0447\u0435\u0441\u043A\u0438\u0445 \u0432\u044B\u0433\u0440\u0443\u0437\u043E\u043A, \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u0443\u0435\u043C\u044B\u0445 \u043F\u0440\u043E\u0435\u043A\u0442\u043E\u043C ASG Racing \u0434\u043B\u044F \u043F\u0443\u0431\u043B\u0438\u043A\u0430\u0446\u0438\u0438 \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442\u043E\u0432, \u0440\u0435\u0439\u0442\u0438\u043D\u0433\u043E\u0432 \u0438 \u043F\u0440\u043E\u0444\u0438\u043B\u0435\u0439 \u0443\u0447\u0430\u0441\u0442\u043D\u0438\u043A\u043E\u0432;</li>\n        <li>\u0438\u0437 \u043E\u0431\u0440\u0430\u0449\u0435\u043D\u0438\u0439 \u0438 \u0441\u043E\u043E\u0431\u0449\u0435\u043D\u0438\u0439, \u043D\u0430\u043F\u0440\u0430\u0432\u043B\u0435\u043D\u043D\u044B\u0445 \u043E\u043F\u0435\u0440\u0430\u0442\u043E\u0440\u0443 \u043F\u043E \u0430\u0434\u0440\u0435\u0441\u0443 <code>itriahon@gmail.com</code>.</li>\n      </ul>\n      <p>\n        \u0415\u0441\u043B\u0438 \u0434\u0430\u043D\u043D\u044B\u0435 \u0443\u0447\u0430\u0441\u0442\u043D\u0438\u043A\u0430 \u0433\u043E\u043D\u043A\u0438 \u043F\u043E\u0441\u0442\u0443\u043F\u0430\u044E\u0442 \u043E\u043F\u0435\u0440\u0430\u0442\u043E\u0440\u0443 \u043D\u0435 \u043D\u0430\u043F\u0440\u044F\u043C\u0443\u044E \u043E\u0442 \u0441\u0443\u0431\u044A\u0435\u043A\u0442\u0430, \u0430 \u0438\u0437 \u043E\u0444\u0438\u0446\u0438\u0430\u043B\u044C\u043D\u044B\u0445 \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442\u043E\u0432,\n        \u043F\u0440\u043E\u0442\u043E\u043A\u043E\u043B\u043E\u0432 \u0438\u043B\u0438 \u0441\u0432\u044F\u0437\u0430\u043D\u043D\u044B\u0445 \u0441 \u043F\u0440\u043E\u0432\u0435\u0434\u0435\u043D\u0438\u0435\u043C \u0433\u043E\u043D\u043A\u0438 \u0442\u0435\u0445\u043D\u0438\u0447\u0435\u0441\u043A\u0438\u0445 \u0441\u0438\u0441\u0442\u0435\u043C, \u043E\u043F\u0435\u0440\u0430\u0442\u043E\u0440 \u043E\u0431\u0440\u0430\u0431\u0430\u0442\u044B\u0432\u0430\u0435\u0442 \u0438\u0445 \u0432 \u043E\u0431\u044A\u0435\u043C\u0435,\n        \u043D\u0435\u043E\u0431\u0445\u043E\u0434\u0438\u043C\u043E\u043C \u0434\u043B\u044F \u0432\u0435\u0434\u0435\u043D\u0438\u044F \u0441\u0442\u0430\u0442\u0438\u0441\u0442\u0438\u043A\u0438, \u0430\u0440\u0445\u0438\u0432\u0430 \u0433\u043E\u043D\u043E\u043A, \u0442\u0443\u0440\u043D\u0438\u0440\u043D\u044B\u0445 \u0442\u0430\u0431\u043B\u0438\u0446 \u0438 \u043F\u0443\u0431\u043B\u0438\u043A\u0430\u0446\u0438\u0438 \u043C\u0430\u0442\u0435\u0440\u0438\u0430\u043B\u043E\u0432 \u043F\u0440\u043E\u0435\u043A\u0442\u0430.\n      </p>"},{"id":"section-5","title":"5. \u0426\u0435\u043B\u0438 \u0438 \u043F\u0440\u0430\u0432\u043E\u0432\u044B\u0435 \u043E\u0441\u043D\u043E\u0432\u0430\u043D\u0438\u044F \u043E\u0431\u0440\u0430\u0431\u043E\u0442\u043A\u0438","html":'<div class="legal-table-wrap">\n        <table class="legal-table">\n          <thead>\n            <tr>\n              <th>\u0426\u0435\u043B\u044C</th>\n              <th>\u0421\u043E\u0441\u0442\u0430\u0432 \u0434\u0430\u043D\u043D\u044B\u0445</th>\n              <th>\u041F\u0440\u0430\u0432\u043E\u0432\u043E\u0435 \u043E\u0441\u043D\u043E\u0432\u0430\u043D\u0438\u0435</th>\n            </tr>\n          </thead>\n          <tbody>\n            <tr>\n              <td>\u041E\u0431\u0435\u0441\u043F\u0435\u0447\u0435\u043D\u0438\u0435 \u0440\u0430\u0431\u043E\u0442\u044B \u0441\u0430\u0439\u0442\u0430, \u0438\u043D\u0442\u0435\u0440\u0444\u0435\u0439\u0441\u0430 \u0438 \u043D\u0430\u0432\u0438\u0433\u0430\u0446\u0438\u0438</td>\n              <td>\u0422\u0435\u0445\u043D\u0438\u0447\u0435\u0441\u043A\u0438\u0435 \u0434\u0430\u043D\u043D\u044B\u0435 \u0443\u0441\u0442\u0440\u043E\u0439\u0441\u0442\u0432\u0430 \u0438 \u0431\u0440\u0430\u0443\u0437\u0435\u0440\u0430, \u0441\u043B\u0443\u0436\u0435\u0431\u043D\u044B\u0435 localStorage-\u043A\u043B\u044E\u0447\u0438</td>\n              <td>\u0421\u0442. 6 \u0447. 1 152-\u0424\u0417, \u043E\u0431\u0440\u0430\u0431\u043E\u0442\u043A\u0430 \u0432 \u043E\u0431\u044A\u0451\u043C\u0435, \u043D\u0435\u043E\u0431\u0445\u043E\u0434\u0438\u043C\u043E\u043C \u0434\u043B\u044F \u0444\u0443\u043D\u043A\u0446\u0438\u043E\u043D\u0438\u0440\u043E\u0432\u0430\u043D\u0438\u044F \u0441\u0430\u0439\u0442\u0430 \u0438 \u0437\u0430\u043F\u0440\u043E\u0448\u0435\u043D\u043D\u043E\u0433\u043E \u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u0435\u043B\u0435\u043C \u0438\u043D\u0442\u0435\u0440\u0444\u0435\u0439\u0441\u0430</td>\n            </tr>\n            <tr>\n              <td>\u0421\u0431\u043E\u0440 \u0441\u0442\u0430\u0442\u0438\u0441\u0442\u0438\u043A\u0438 \u043F\u043E\u0441\u0435\u0449\u0430\u0435\u043C\u043E\u0441\u0442\u0438 \u0438 \u0443\u043B\u0443\u0447\u0448\u0435\u043D\u0438\u0435 \u0441\u0430\u0439\u0442\u0430</td>\n              <td>Cookie \u0438 localStorage \u0438\u0434\u0435\u043D\u0442\u0438\u0444\u0438\u043A\u0430\u0442\u043E\u0440\u044B \u042F\u043D\u0434\u0435\u043A\u0441 \u041C\u0435\u0442\u0440\u0438\u043A\u0438, \u0434\u0430\u043D\u043D\u044B\u0435 \u043E \u043F\u043E\u0441\u0435\u0449\u0435\u043D\u0438\u044F\u0445 \u0438 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044F\u0445 \u043D\u0430 \u0441\u0442\u0440\u0430\u043D\u0438\u0446\u0430\u0445</td>\n              <td>\u0421\u043E\u0433\u043B\u0430\u0441\u0438\u0435 \u0441\u0443\u0431\u044A\u0435\u043A\u0442\u0430 \u043F\u0435\u0440\u0441\u043E\u043D\u0430\u043B\u044C\u043D\u044B\u0445 \u0434\u0430\u043D\u043D\u044B\u0445, \u0432\u044B\u0440\u0430\u0436\u0435\u043D\u043D\u043E\u0435 \u0447\u0435\u0440\u0435\u0437 \u0431\u0430\u043D\u043D\u0435\u0440 cookies/\u0430\u043D\u0430\u043B\u0438\u0442\u0438\u043A\u0438</td>\n            </tr>\n            <tr>\n              <td>\u0423\u0447\u0451\u0442 \u043E\u0434\u043D\u043E\u0433\u043E \u0433\u043E\u043B\u043E\u0441\u0430 \u043D\u0430 \u0441\u043B\u043E\u0442 \u0447\u0430\u0441\u043E\u0432\u043E\u0439 \u0433\u043E\u043D\u043A\u0438 \u0438 \u043F\u0440\u0435\u0434\u043E\u0442\u0432\u0440\u0430\u0449\u0435\u043D\u0438\u0435 \u043F\u043E\u0432\u0442\u043E\u0440\u043D\u043E\u0433\u043E \u0433\u043E\u043B\u043E\u0441\u043E\u0432\u0430\u043D\u0438\u044F</td>\n              <td>\u0421\u043B\u0443\u0447\u0430\u0439\u043D\u044B\u0439 \u0431\u0440\u0430\u0443\u0437\u0435\u0440\u043D\u044B\u0439 \u0438\u0434\u0435\u043D\u0442\u0438\u0444\u0438\u043A\u0430\u0442\u043E\u0440, \u0438\u0434\u0435\u043D\u0442\u0438\u0444\u0438\u043A\u0430\u0442\u043E\u0440 \u0441\u043B\u043E\u0442\u0430, \u043E\u0442\u043C\u0435\u0442\u043A\u0430 \u043E \u0433\u043E\u043B\u043E\u0441\u0435</td>\n              <td>\u0418\u043D\u0438\u0446\u0438\u0430\u0442\u0438\u0432\u0430 \u0438 \u0434\u043E\u0431\u0440\u043E\u0432\u043E\u043B\u044C\u043D\u043E\u0435 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0435 \u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u0435\u043B\u044F \u043F\u0440\u0438 \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u043D\u0438\u0438 \u0444\u0443\u043D\u043A\u0446\u0438\u043E\u043D\u0430\u043B\u0430 \u0433\u043E\u043B\u043E\u0441\u043E\u0432\u0430\u043D\u0438\u044F</td>\n            </tr>\n            <tr>\n              <td>\u0421\u0431\u043E\u0440, \u0441\u0438\u0441\u0442\u0435\u043C\u0430\u0442\u0438\u0437\u0430\u0446\u0438\u044F \u0438 \u0445\u0440\u0430\u043D\u0435\u043D\u0438\u0435 \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442\u043E\u0432 \u0433\u043E\u043D\u043E\u043A, \u0441\u0442\u0430\u0442\u0438\u0441\u0442\u0438\u043A\u0438, \u0442\u0443\u0440\u043D\u0438\u0440\u043D\u044B\u0445 \u0442\u0430\u0431\u043B\u0438\u0446 \u0438 \u0430\u0440\u0445\u0438\u0432\u0430 \u0437\u0430\u0435\u0437\u0434\u043E\u0432</td>\n              <td>\u0418\u043C\u044F \u0438\u043B\u0438 \u043D\u0438\u043A \u0443\u0447\u0430\u0441\u0442\u043D\u0438\u043A\u0430, <code>player_id</code>, <code>public_id</code>, \u043F\u043E\u0437\u0438\u0446\u0438\u0438, \u043A\u0440\u0443\u0433\u0438, \u043B\u0443\u0447\u0448\u0438\u0435 \u043A\u0440\u0443\u0433\u0438, \u043E\u0447\u043A\u0438, \u0448\u0442\u0440\u0430\u0444\u044B, \u0438\u0441\u0442\u043E\u0440\u0438\u044F \u0433\u043E\u043D\u043E\u043A, \u0441\u0432\u0435\u0434\u0435\u043D\u0438\u044F \u043E\u0431 \u0430\u0432\u0442\u043E\u043C\u043E\u0431\u0438\u043B\u0435 \u0438 \u0442\u0440\u0430\u0441\u0441\u0435, \u043F\u0440\u043E\u0438\u0437\u0432\u043E\u0434\u043D\u044B\u0435 \u0441\u0442\u0430\u0442\u0438\u0441\u0442\u0438\u0447\u0435\u0441\u043A\u0438\u0435 \u043F\u043E\u043A\u0430\u0437\u0430\u0442\u0435\u043B\u0438</td>\n              <td>\u0421\u043E\u0433\u043B\u0430\u0441\u0438\u0435 \u0441\u0443\u0431\u044A\u0435\u043A\u0442\u0430 \u043F\u0435\u0440\u0441\u043E\u043D\u0430\u043B\u044C\u043D\u044B\u0445 \u0434\u0430\u043D\u043D\u044B\u0445 \u043D\u0430 \u0443\u0447\u0430\u0441\u0442\u0438\u0435 \u0432 \u043F\u0440\u043E\u0435\u043A\u0442\u0435 \u0438 \u043E\u0431\u0440\u0430\u0431\u043E\u0442\u043A\u0443 \u0441\u0432\u044F\u0437\u0430\u043D\u043D\u044B\u0445 \u0441 \u044D\u0442\u0438\u043C \u0434\u0430\u043D\u043D\u044B\u0445, \u0430 \u0442\u0430\u043A\u0436\u0435 \u0438\u043D\u044B\u0435 \u043E\u0441\u043D\u043E\u0432\u0430\u043D\u0438\u044F, \u043F\u0440\u0435\u0434\u0443\u0441\u043C\u043E\u0442\u0440\u0435\u043D\u043D\u044B\u0435 \u0437\u0430\u043A\u043E\u043D\u043E\u0434\u0430\u0442\u0435\u043B\u044C\u0441\u0442\u0432\u043E\u043C \u0420\u0424</td>\n            </tr>\n            <tr>\n              <td>\u041F\u0443\u0431\u043B\u0438\u043A\u0430\u0446\u0438\u044F \u043F\u0443\u0431\u043B\u0438\u0447\u043D\u044B\u0445 \u043F\u0440\u043E\u0444\u0438\u043B\u0435\u0439 \u0443\u0447\u0430\u0441\u0442\u043D\u0438\u043A\u043E\u0432, \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442\u043E\u0432 \u0433\u043E\u043D\u043E\u043A, \u0440\u0435\u0439\u0442\u0438\u043D\u0433\u043E\u0432 \u0438 \u0430\u0440\u0445\u0438\u0432\u0430 \u043F\u0440\u043E\u0435\u043A\u0442\u0430 \u0432 \u0441\u0435\u0442\u0438 \u0418\u043D\u0442\u0435\u0440\u043D\u0435\u0442</td>\n              <td>\u0418\u043C\u044F \u0438\u043B\u0438 \u043D\u0438\u043A \u0443\u0447\u0430\u0441\u0442\u043D\u0438\u043A\u0430, <code>public_id</code>, \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442\u044B, \u0434\u043E\u0441\u0442\u0438\u0436\u0435\u043D\u0438\u044F, \u0438\u0441\u0442\u043E\u0440\u0438\u044F \u0432\u044B\u0441\u0442\u0443\u043F\u043B\u0435\u043D\u0438\u0439, \u0448\u0442\u0440\u0430\u0444\u044B, \u043B\u0443\u0447\u0448\u0438\u0435 \u043A\u0440\u0443\u0433\u0438 \u0438 \u0438\u043D\u044B\u0435 \u0434\u0430\u043D\u043D\u044B\u0435, \u0432\u043A\u043B\u044E\u0447\u0435\u043D\u043D\u044B\u0435 \u0432 \u043F\u0443\u0431\u043B\u0438\u0447\u043D\u044B\u0439 \u043F\u0440\u043E\u0444\u0438\u043B\u044C \u0438 \u0430\u0440\u0445\u0438\u0432 \u0433\u043E\u043D\u043E\u043A</td>\n              <td>\u0421\u043E\u0433\u043B\u0430\u0441\u0438\u0435 \u0441\u0443\u0431\u044A\u0435\u043A\u0442\u0430 \u043F\u0435\u0440\u0441\u043E\u043D\u0430\u043B\u044C\u043D\u044B\u0445 \u0434\u0430\u043D\u043D\u044B\u0445 \u043D\u0430 \u043E\u0431\u0440\u0430\u0431\u043E\u0442\u043A\u0443 \u0438, \u043A\u043E\u0433\u0434\u0430 \u044D\u0442\u043E \u0442\u0440\u0435\u0431\u0443\u0435\u0442\u0441\u044F \u0437\u0430\u043A\u043E\u043D\u043E\u0434\u0430\u0442\u0435\u043B\u044C\u0441\u0442\u0432\u043E\u043C \u0420\u0424, \u043E\u0442\u0434\u0435\u043B\u044C\u043D\u043E\u0435 \u0441\u043E\u0433\u043B\u0430\u0441\u0438\u0435 \u043D\u0430 \u0440\u0430\u0441\u043F\u0440\u043E\u0441\u0442\u0440\u0430\u043D\u0435\u043D\u0438\u0435 \u043F\u0435\u0440\u0441\u043E\u043D\u0430\u043B\u044C\u043D\u044B\u0445 \u0434\u0430\u043D\u043D\u044B\u0445</td>\n            </tr>\n            <tr>\n              <td>\u041E\u0431\u0440\u0430\u0431\u043E\u0442\u043A\u0430 \u0437\u0430\u043F\u0440\u043E\u0441\u043E\u0432 \u0441\u0443\u0431\u044A\u0435\u043A\u0442\u043E\u0432 \u043F\u0435\u0440\u0441\u043E\u043D\u0430\u043B\u044C\u043D\u044B\u0445 \u0434\u0430\u043D\u043D\u044B\u0445</td>\n              <td>\u041A\u043E\u043D\u0442\u0430\u043A\u0442\u043D\u044B\u0435 \u0434\u0430\u043D\u043D\u044B\u0435, \u043A\u043E\u0442\u043E\u0440\u044B\u0435 \u0441\u0443\u0431\u044A\u0435\u043A\u0442 \u0443\u043A\u0430\u0436\u0435\u0442 \u0432 \u043E\u0431\u0440\u0430\u0449\u0435\u043D\u0438\u0438, \u0438 \u0441\u0432\u0435\u0434\u0435\u043D\u0438\u044F, \u043D\u0435\u043E\u0431\u0445\u043E\u0434\u0438\u043C\u044B\u0435 \u0434\u043B\u044F \u043E\u0442\u0432\u0435\u0442\u0430</td>\n              <td>152-\u0424\u0417, \u0438\u043D\u044B\u0435 \u043E\u0431\u044F\u0437\u0430\u0442\u0435\u043B\u044C\u043D\u044B\u0435 \u0442\u0440\u0435\u0431\u043E\u0432\u0430\u043D\u0438\u044F \u0437\u0430\u043A\u043E\u043D\u043E\u0434\u0430\u0442\u0435\u043B\u044C\u0441\u0442\u0432\u0430 \u0420\u0424</td>\n            </tr>\n          </tbody>\n        </table>\n      </div>'},{"id":"section-6","title":"6. \u041F\u043E\u0440\u044F\u0434\u043E\u043A \u0438 \u0443\u0441\u043B\u043E\u0432\u0438\u044F \u043E\u0431\u0440\u0430\u0431\u043E\u0442\u043A\u0438","html":"<ul>\n        <li>\u041E\u0431\u0440\u0430\u0431\u043E\u0442\u043A\u0430 \u043F\u0435\u0440\u0441\u043E\u043D\u0430\u043B\u044C\u043D\u044B\u0445 \u0434\u0430\u043D\u043D\u044B\u0445 \u043E\u0441\u0443\u0449\u0435\u0441\u0442\u0432\u043B\u044F\u0435\u0442\u0441\u044F \u0441 \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u043D\u0438\u0435\u043C \u0441\u0440\u0435\u0434\u0441\u0442\u0432 \u0430\u0432\u0442\u043E\u043C\u0430\u0442\u0438\u0437\u0430\u0446\u0438\u0438 \u0438 \u0431\u0435\u0437 \u043D\u0438\u0445.</li>\n        <li>\u0414\u0430\u043D\u043D\u044B\u0435 \u0443\u0447\u0430\u0441\u0442\u043D\u0438\u043A\u043E\u0432 \u0433\u043E\u043D\u043E\u043A \u043E\u0431\u0440\u0430\u0431\u0430\u0442\u044B\u0432\u0430\u044E\u0442\u0441\u044F \u0432 \u043E\u0431\u044A\u0435\u043C\u0435, \u043D\u0435\u043E\u0431\u0445\u043E\u0434\u0438\u043C\u043E\u043C \u0434\u043B\u044F \u0444\u043E\u0440\u043C\u0438\u0440\u043E\u0432\u0430\u043D\u0438\u044F \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442\u043E\u0432, \u0440\u0435\u0439\u0442\u0438\u043D\u0433\u043E\u0432, \u0430\u0440\u0445\u0438\u0432\u043E\u0432 \u0433\u043E\u043D\u043E\u043A \u0438 \u043F\u0443\u0431\u043B\u0438\u0447\u043D\u044B\u0445 \u043F\u0440\u043E\u0444\u0438\u043B\u0435\u0439 \u043F\u0440\u043E\u0435\u043A\u0442\u0430.</li>\n        <li>\u0415\u0441\u043B\u0438 \u0432 \u0438\u0441\u0445\u043E\u0434\u043D\u044B\u0445 \u043F\u0440\u043E\u0442\u043E\u043A\u043E\u043B\u0430\u0445 \u0433\u043E\u043D\u043A\u0438 \u0441\u043E\u0434\u0435\u0440\u0436\u0430\u0442\u0441\u044F \u0440\u0435\u0430\u043B\u044C\u043D\u043E\u0435 \u0438\u043C\u044F, \u0444\u0430\u043C\u0438\u043B\u0438\u044F \u0438\u043B\u0438 \u043D\u0438\u043A \u0443\u0447\u0430\u0441\u0442\u043D\u0438\u043A\u0430, \u0442\u0430\u043A\u0438\u0435 \u0434\u0430\u043D\u043D\u044B\u0435 \u043C\u043E\u0433\u0443\u0442 \u0431\u044B\u0442\u044C \u0432\u043A\u043B\u044E\u0447\u0435\u043D\u044B \u0432 \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442\u044B \u0437\u0430\u0435\u0437\u0434\u043E\u0432 \u0438 \u043F\u0440\u043E\u0444\u0438\u043B\u044C \u0443\u0447\u0430\u0441\u0442\u043D\u0438\u043A\u0430 \u0432 \u043F\u0440\u0435\u0434\u0435\u043B\u0430\u0445 \u0437\u0430\u044F\u0432\u043B\u0435\u043D\u043D\u044B\u0445 \u0446\u0435\u043B\u0435\u0439 \u043E\u0431\u0440\u0430\u0431\u043E\u0442\u043A\u0438.</li>\n        <li>\u041F\u0443\u0431\u043B\u0438\u043A\u0430\u0446\u0438\u044F \u043E\u0442\u043A\u0440\u044B\u0442\u044B\u0445 \u043F\u0440\u043E\u0444\u0438\u043B\u0435\u0439, \u0442\u0430\u0431\u043B\u0438\u0446 \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442\u043E\u0432 \u0438 \u0430\u0440\u0445\u0438\u0432\u043E\u0432 \u0433\u043E\u043D\u043E\u043A \u0434\u043E\u043F\u0443\u0441\u043A\u0430\u0435\u0442\u0441\u044F \u0442\u043E\u043B\u044C\u043A\u043E \u0432 \u043E\u0431\u044A\u0435\u043C\u0435, \u043D\u0435\u043E\u0431\u0445\u043E\u0434\u0438\u043C\u043E\u043C \u0434\u043B\u044F \u0446\u0435\u043B\u0435\u0439 \u043F\u0440\u043E\u0435\u043A\u0442\u0430 \u0438 \u043F\u0440\u0438 \u043D\u0430\u043B\u0438\u0447\u0438\u0438 \u043D\u0430\u0434\u043B\u0435\u0436\u0430\u0449\u0435\u0433\u043E \u043F\u0440\u0430\u0432\u043E\u0432\u043E\u0433\u043E \u043E\u0441\u043D\u043E\u0432\u0430\u043D\u0438\u044F.</li>\n        <li>\u041E\u043F\u0435\u0440\u0430\u0442\u043E\u0440 \u043F\u0440\u0438\u043D\u0438\u043C\u0430\u0435\u0442 \u043C\u0435\u0440\u044B \u043F\u043E \u043C\u0438\u043D\u0438\u043C\u0438\u0437\u0430\u0446\u0438\u0438 \u043E\u0431\u044A\u0451\u043C\u0430 \u0441\u043E\u0431\u0438\u0440\u0430\u0435\u043C\u044B\u0445 \u0434\u0430\u043D\u043D\u044B\u0445 \u0438 \u043D\u0435 \u0437\u0430\u0433\u0440\u0443\u0436\u0430\u0435\u0442 \u042F\u043D\u0434\u0435\u043A\u0441 \u041C\u0435\u0442\u0440\u0438\u043A\u0443 \u0434\u043E \u043F\u043E\u043B\u0443\u0447\u0435\u043D\u0438\u044F \u0441\u043E\u0433\u043B\u0430\u0441\u0438\u044F \u043D\u0430 \u0430\u043D\u0430\u043B\u0438\u0442\u0438\u043A\u0443.</li>\n        <li>\u041E\u043F\u0435\u0440\u0430\u0442\u043E\u0440 \u043D\u0435 \u0434\u043E\u043B\u0436\u0435\u043D \u043F\u0435\u0440\u0435\u0434\u0430\u0432\u0430\u0442\u044C \u0432 \u0441\u0438\u0441\u0442\u0435\u043C\u044B \u0430\u043D\u0430\u043B\u0438\u0442\u0438\u043A\u0438 \u0434\u0430\u043D\u043D\u044B\u0435, \u043F\u0440\u044F\u043C\u043E \u0438\u0434\u0435\u043D\u0442\u0438\u0444\u0438\u0446\u0438\u0440\u0443\u044E\u0449\u0438\u0435 \u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u0435\u043B\u044F: \u0424\u0418\u041E, e-mail, \u0442\u0435\u043B\u0435\u0444\u043E\u043D, \u0430\u0434\u0440\u0435\u0441 \u0438 \u0438\u043D\u044B\u0435 \u043F\u043E\u0434\u043E\u0431\u043D\u044B\u0435 \u0441\u0432\u0435\u0434\u0435\u043D\u0438\u044F.</li>\n        <li>\u041E\u043F\u0435\u0440\u0430\u0442\u043E\u0440 \u0440\u0430\u0441\u0441\u043C\u0430\u0442\u0440\u0438\u0432\u0430\u0435\u0442 \u043E\u0431\u0440\u0430\u0449\u0435\u043D\u0438\u044F \u0441\u0443\u0431\u044A\u0435\u043A\u0442\u043E\u0432 \u043F\u0435\u0440\u0441\u043E\u043D\u0430\u043B\u044C\u043D\u044B\u0445 \u0434\u0430\u043D\u043D\u044B\u0445 \u043E\u0431 \u0443\u0442\u043E\u0447\u043D\u0435\u043D\u0438\u0438, \u0431\u043B\u043E\u043A\u0438\u0440\u043E\u0432\u0430\u043D\u0438\u0438, \u0443\u0434\u0430\u043B\u0435\u043D\u0438\u0438 \u0438\u043B\u0438 \u043F\u0440\u0435\u043A\u0440\u0430\u0449\u0435\u043D\u0438\u0438 \u0440\u0430\u0441\u043F\u0440\u043E\u0441\u0442\u0440\u0430\u043D\u0435\u043D\u0438\u044F \u0434\u0430\u043D\u043D\u044B\u0445 \u0432 \u0441\u043B\u0443\u0447\u0430\u044F\u0445 \u0438 \u0441\u0440\u043E\u043A\u0438, \u043F\u0440\u0435\u0434\u0443\u0441\u043C\u043E\u0442\u0440\u0435\u043D\u043D\u044B\u0435 \u0437\u0430\u043A\u043E\u043D\u043E\u0434\u0430\u0442\u0435\u043B\u044C\u0441\u0442\u0432\u043E\u043C \u0420\u0424.</li>\n        <li>\u041E\u0442\u043A\u0430\u0437 \u043E\u0442 \u0430\u043D\u0430\u043B\u0438\u0442\u0438\u043A\u0438 \u043D\u0435 \u043E\u0433\u0440\u0430\u043D\u0438\u0447\u0438\u0432\u0430\u0435\u0442 \u0434\u043E\u0441\u0442\u0443\u043F \u043A \u043E\u0441\u043D\u043E\u0432\u043D\u043E\u043C\u0443 \u0441\u043E\u0434\u0435\u0440\u0436\u0438\u043C\u043E\u043C\u0443 \u0441\u0430\u0439\u0442\u0430.</li>\n      </ul>"},{"id":"section-7","title":"7. \u0418\u0441\u043F\u043E\u043B\u044C\u0437\u0443\u0435\u043C\u044B\u0435 \u0441\u0435\u0440\u0432\u0438\u0441\u044B \u0438 \u0432\u043E\u0437\u043C\u043E\u0436\u043D\u0430\u044F \u043F\u0435\u0440\u0435\u0434\u0430\u0447\u0430 \u0434\u0430\u043D\u043D\u044B\u0445 \u0442\u0440\u0435\u0442\u044C\u0438\u043C \u043B\u0438\u0446\u0430\u043C","html":"<p>\u0414\u043B\u044F \u0440\u0430\u0431\u043E\u0442\u044B \u043E\u0442\u0434\u0435\u043B\u044C\u043D\u044B\u0445 \u0444\u0443\u043D\u043A\u0446\u0438\u0439 \u0441\u0430\u0439\u0442\u0430 \u043C\u043E\u0433\u0443\u0442 \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u044C\u0441\u044F \u0441\u0442\u043E\u0440\u043E\u043D\u043D\u0438\u0435 \u0441\u0435\u0440\u0432\u0438\u0441\u044B \u0438 \u0438\u043D\u0444\u0440\u0430\u0441\u0442\u0440\u0443\u043A\u0442\u0443\u0440\u0430:</p>\n      <ul>\n        <li>\u042F\u043D\u0434\u0435\u043A\u0441 \u041C\u0435\u0442\u0440\u0438\u043A\u0430 \u2014 \u0434\u043B\u044F \u0432\u0435\u0431-\u0430\u043D\u0430\u043B\u0438\u0442\u0438\u043A\u0438 \u043F\u043E\u0441\u043B\u0435 \u043F\u043E\u043B\u0443\u0447\u0435\u043D\u0438\u044F \u0441\u043E\u0433\u043B\u0430\u0441\u0438\u044F \u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u0435\u043B\u044F;</li>\n        <li>GitHub Pages \u2014 \u0434\u043B\u044F \u043F\u0443\u0431\u043B\u0438\u043A\u0430\u0446\u0438\u0438 \u0441\u0442\u0430\u0442\u0438\u0447\u0435\u0441\u043A\u0438\u0445 \u0441\u0442\u0440\u0430\u043D\u0438\u0446 \u0441\u0430\u0439\u0442\u0430;</li>\n        <li>Cloudflare Workers \u0438 GitHub API/Issues \u2014 \u0434\u043B\u044F \u0440\u0430\u0431\u043E\u0442\u044B \u043C\u0435\u0445\u0430\u043D\u0438\u043A\u0438 \u0433\u043E\u043B\u043E\u0441\u043E\u0432\u0430\u043D\u0438\u044F \u0437\u0430 \u0441\u043B\u043E\u0442 \u0447\u0430\u0441\u043E\u0432\u043E\u0439 \u0433\u043E\u043D\u043A\u0438.</li>\n      </ul>\n      <p>\n        \u0414\u0430\u043D\u043D\u044B\u0435, \u0432\u043A\u043B\u044E\u0447\u0435\u043D\u043D\u044B\u0435 \u0432 \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442\u044B \u0433\u043E\u043D\u043E\u043A, \u0430\u0440\u0445\u0438\u0432\u044B, \u0440\u0435\u0439\u0442\u0438\u043D\u0433\u0438 \u0438 \u043F\u0443\u0431\u043B\u0438\u0447\u043D\u044B\u0435 \u043F\u0440\u043E\u0444\u0438\u043B\u0438 \u0443\u0447\u0430\u0441\u0442\u043D\u0438\u043A\u043E\u0432, \u0440\u0430\u0437\u043C\u0435\u0449\u0430\u044E\u0442\u0441\u044F\n        \u043D\u0430 \u0441\u0430\u0439\u0442\u0435 \u0432 \u043E\u0442\u043A\u0440\u044B\u0442\u043E\u043C \u0434\u043E\u0441\u0442\u0443\u043F\u0435 \u0438 \u043C\u043E\u0433\u0443\u0442 \u0431\u044B\u0442\u044C \u0434\u043E\u0441\u0442\u0443\u043F\u043D\u044B \u043D\u0435\u043E\u043F\u0440\u0435\u0434\u0435\u043B\u0435\u043D\u043D\u043E\u043C\u0443 \u043A\u0440\u0443\u0433\u0443 \u043B\u0438\u0446 \u0432 \u0441\u0435\u0442\u0438 \u0418\u043D\u0442\u0435\u0440\u043D\u0435\u0442. \u041E\u043F\u0435\u0440\u0430\u0442\u043E\u0440\n        \u043E\u0431\u044F\u0437\u0430\u043D \u043E\u0433\u0440\u0430\u043D\u0438\u0447\u0438\u0432\u0430\u0442\u044C \u0441\u043E\u0441\u0442\u0430\u0432 \u043F\u0443\u0431\u043B\u0438\u043A\u0443\u0435\u043C\u044B\u0445 \u0434\u0430\u043D\u043D\u044B\u0445 \u0438 \u043F\u0440\u0435\u043A\u0440\u0430\u0449\u0430\u0442\u044C \u0438\u0445 \u0440\u0430\u0441\u043F\u0440\u043E\u0441\u0442\u0440\u0430\u043D\u0435\u043D\u0438\u0435 \u043F\u0440\u0438 \u043D\u0430\u043B\u0438\u0447\u0438\u0438 \u043E\u0441\u043D\u043E\u0432\u0430\u043D\u0438\u0439,\n        \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D\u043D\u044B\u0445 \u0437\u0430\u043A\u043E\u043D\u043E\u0434\u0430\u0442\u0435\u043B\u044C\u0441\u0442\u0432\u043E\u043C \u0420\u0424.\n      </p>\n      <p>\n        \u041F\u0435\u0440\u0435\u0434\u0430\u0447\u0430 \u0434\u0430\u043D\u043D\u044B\u0445 \u0443\u043A\u0430\u0437\u0430\u043D\u043D\u044B\u043C \u0441\u0435\u0440\u0432\u0438\u0441\u0430\u043C \u043E\u0441\u0443\u0449\u0435\u0441\u0442\u0432\u043B\u044F\u0435\u0442\u0441\u044F \u0432 \u043E\u0431\u044A\u0451\u043C\u0435, \u043D\u0435\u043E\u0431\u0445\u043E\u0434\u0438\u043C\u043E\u043C \u0434\u043B\u044F \u0438\u0445 \u0442\u0435\u0445\u043D\u0438\u0447\u0435\u0441\u043A\u043E\u0439 \u0440\u0430\u0431\u043E\u0442\u044B.\n        \u0415\u0441\u043B\u0438 \u043A\u043E\u043D\u043A\u0440\u0435\u0442\u043D\u0430\u044F \u043F\u0435\u0440\u0435\u0434\u0430\u0447\u0430 \u043F\u043E\u0434\u043F\u0430\u0434\u0430\u0435\u0442 \u043F\u043E\u0434 \u043F\u0440\u0438\u0437\u043D\u0430\u043A\u0438 \u0442\u0440\u0430\u043D\u0441\u0433\u0440\u0430\u043D\u0438\u0447\u043D\u043E\u0439 \u043F\u0435\u0440\u0435\u0434\u0430\u0447\u0438 \u043F\u0435\u0440\u0441\u043E\u043D\u0430\u043B\u044C\u043D\u044B\u0445 \u0434\u0430\u043D\u043D\u044B\u0445 \u0432\n        \u043F\u043E\u043D\u0438\u043C\u0430\u043D\u0438\u0438 \u0441\u0442\u0430\u0442\u044C\u0438 12 152-\u0424\u0417, \u043E\u043F\u0435\u0440\u0430\u0442\u043E\u0440 \u043E\u0431\u044F\u0437\u0430\u043D \u0432\u044B\u043F\u043E\u043B\u043D\u0438\u0442\u044C \u0442\u0440\u0435\u0431\u043E\u0432\u0430\u043D\u0438\u044F \u0443\u043A\u0430\u0437\u0430\u043D\u043D\u043E\u0439 \u0441\u0442\u0430\u0442\u044C\u0438, \u0432\u043A\u043B\u044E\u0447\u0430\u044F \u043E\u0442\u0434\u0435\u043B\u044C\u043D\u043E\u0435\n        \u0443\u0432\u0435\u0434\u043E\u043C\u043B\u0435\u043D\u0438\u0435 \u0420\u043E\u0441\u043A\u043E\u043C\u043D\u0430\u0434\u0437\u043E\u0440\u0430 \u043F\u0440\u0438 \u043D\u0435\u043E\u0431\u0445\u043E\u0434\u0438\u043C\u043E\u0441\u0442\u0438.\n      </p>\n      <p>\u041F\u043E \u0441\u043E\u0441\u0442\u043E\u044F\u043D\u0438\u044E \u043D\u0430 30.04.2026 Google Analytics \u043D\u0430 \u0441\u0430\u0439\u0442\u0430\u0445 \u043F\u0440\u043E\u0435\u043A\u0442\u0430 \u043D\u0435 \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u0443\u0435\u0442\u0441\u044F.</p>"},{"id":"section-8","title":"8. \u0421\u0440\u043E\u043A\u0438 \u043E\u0431\u0440\u0430\u0431\u043E\u0442\u043A\u0438 \u0438 \u0445\u0440\u0430\u043D\u0435\u043D\u0438\u044F","html":"<ul>\n        <li>\u0434\u0430\u043D\u043D\u044B\u0435 \u0430\u043D\u0430\u043B\u0438\u0442\u0438\u043A\u0438 \u043E\u0431\u0440\u0430\u0431\u0430\u0442\u044B\u0432\u0430\u044E\u0442\u0441\u044F \u0432 \u0441\u0440\u043E\u043A\u0438, \u043E\u043F\u0440\u0435\u0434\u0435\u043B\u044F\u0435\u043C\u044B\u0435 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0430\u043C\u0438 \u042F\u043D\u0434\u0435\u043A\u0441 \u041C\u0435\u0442\u0440\u0438\u043A\u0438 \u0438 \u043F\u043E\u043B\u0438\u0442\u0438\u043A\u043E\u0439 \u0441\u0435\u0440\u0432\u0438\u0441\u0430;</li>\n        <li>\u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0430 \u0441\u043E\u0433\u043B\u0430\u0441\u0438\u044F \u043D\u0430 \u0430\u043D\u0430\u043B\u0438\u0442\u0438\u043A\u0443 \u0445\u0440\u0430\u043D\u0438\u0442\u0441\u044F \u0432 \u0431\u0440\u0430\u0443\u0437\u0435\u0440\u0435 \u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u0435\u043B\u044F \u0434\u043E \u0438\u0437\u043C\u0435\u043D\u0435\u043D\u0438\u044F \u0432\u044B\u0431\u043E\u0440\u0430 \u0438\u043B\u0438 \u043E\u0431\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u044F \u0432\u0435\u0440\u0441\u0438\u0438 \u0441\u043E\u0433\u043B\u0430\u0441\u0438\u044F;</li>\n        <li>\u0431\u0440\u0430\u0443\u0437\u0435\u0440\u043D\u044B\u0439 \u0438\u0434\u0435\u043D\u0442\u0438\u0444\u0438\u043A\u0430\u0442\u043E\u0440 \u0434\u043B\u044F \u0433\u043E\u043B\u043E\u0441\u043E\u0432\u0430\u043D\u0438\u044F \u0445\u0440\u0430\u043D\u0438\u0442\u0441\u044F \u0432 \u0431\u0440\u0430\u0443\u0437\u0435\u0440\u0435 \u0434\u043E 12 \u043C\u0435\u0441\u044F\u0446\u0435\u0432 \u043B\u0438\u0431\u043E \u0434\u043E \u043E\u0447\u0438\u0441\u0442\u043A\u0438 localStorage \u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u0435\u043B\u0435\u043C;</li>\n        <li>\u0441\u043B\u0443\u0436\u0435\u0431\u043D\u044B\u0435 \u0434\u0430\u043D\u043D\u044B\u0435 \u0438\u043D\u0442\u0435\u0440\u0444\u0435\u0439\u0441\u0430 \u0445\u0440\u0430\u043D\u044F\u0442\u0441\u044F \u0434\u043E \u043E\u0447\u0438\u0441\u0442\u043A\u0438 \u0431\u0440\u0430\u0443\u0437\u0435\u0440\u0430 \u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u0435\u043B\u0435\u043C \u0438\u043B\u0438 \u0434\u043E \u0437\u0430\u043C\u0435\u043D\u044B \u043D\u043E\u0432\u044B\u043C\u0438 \u0437\u043D\u0430\u0447\u0435\u043D\u0438\u044F\u043C\u0438;</li>\n        <li>\u0434\u0430\u043D\u043D\u044B\u0435 \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442\u043E\u0432 \u0433\u043E\u043D\u043E\u043A, \u0430\u0440\u0445\u0438\u0432\u044B, \u0440\u0435\u0439\u0442\u0438\u043D\u0433\u0438, \u043F\u0443\u0431\u043B\u0438\u0447\u043D\u044B\u0435 \u043F\u0440\u043E\u0444\u0438\u043B\u0438 \u0443\u0447\u0430\u0441\u0442\u043D\u0438\u043A\u043E\u0432 \u0438 \u043F\u0440\u043E\u0438\u0437\u0432\u043E\u0434\u043D\u0430\u044F \u0441\u0442\u0430\u0442\u0438\u0441\u0442\u0438\u043A\u0430 \u0445\u0440\u0430\u043D\u044F\u0442\u0441\u044F \u0432 \u0442\u0435\u0447\u0435\u043D\u0438\u0435 \u0441\u0440\u043E\u043A\u0430 \u0441\u0443\u0449\u0435\u0441\u0442\u0432\u043E\u0432\u0430\u043D\u0438\u044F \u043F\u0440\u043E\u0435\u043A\u0442\u0430 \u043B\u0438\u0431\u043E \u0434\u043E \u0434\u043E\u0441\u0442\u0438\u0436\u0435\u043D\u0438\u044F \u0446\u0435\u043B\u0435\u0439 \u043E\u0431\u0440\u0430\u0431\u043E\u0442\u043A\u0438, \u0430 \u043F\u0440\u0438 \u043F\u043E\u0441\u0442\u0443\u043F\u043B\u0435\u043D\u0438\u0438 \u043E\u0431\u043E\u0441\u043D\u043E\u0432\u0430\u043D\u043D\u043E\u0433\u043E \u0442\u0440\u0435\u0431\u043E\u0432\u0430\u043D\u0438\u044F \u0441\u0443\u0431\u044A\u0435\u043A\u0442\u0430 \u2014 \u0434\u043E \u043E\u0433\u0440\u0430\u043D\u0438\u0447\u0435\u043D\u0438\u044F \u0440\u0430\u0441\u043F\u0440\u043E\u0441\u0442\u0440\u0430\u043D\u0435\u043D\u0438\u044F, \u043E\u0431\u0435\u0437\u043B\u0438\u0447\u0438\u0432\u0430\u043D\u0438\u044F \u0438\u043B\u0438 \u0443\u0434\u0430\u043B\u0435\u043D\u0438\u044F \u0434\u0430\u043D\u043D\u044B\u0445, \u0435\u0441\u043B\u0438 \u0438\u043D\u043E\u0435 \u043D\u0435 \u0442\u0440\u0435\u0431\u0443\u0435\u0442\u0441\u044F \u0437\u0430\u043A\u043E\u043D\u043E\u043C;</li>\n        <li>\u043E\u0431\u0440\u0430\u0449\u0435\u043D\u0438\u044F \u0441\u0443\u0431\u044A\u0435\u043A\u0442\u043E\u0432 \u043F\u0435\u0440\u0441\u043E\u043D\u0430\u043B\u044C\u043D\u044B\u0445 \u0434\u0430\u043D\u043D\u044B\u0445 \u0438 \u043F\u0435\u0440\u0435\u043F\u0438\u0441\u043A\u0430 \u043F\u043E \u043D\u0438\u043C \u0445\u0440\u0430\u043D\u044F\u0442\u0441\u044F \u0432 \u0442\u0435\u0447\u0435\u043D\u0438\u0435 3 \u043B\u0435\u0442 \u043F\u043E\u0441\u043B\u0435 \u0437\u0430\u0432\u0435\u0440\u0448\u0435\u043D\u0438\u044F \u0440\u0430\u0441\u0441\u043C\u043E\u0442\u0440\u0435\u043D\u0438\u044F \u0441\u043E\u043E\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u0443\u044E\u0449\u0435\u0433\u043E \u043E\u0431\u0440\u0430\u0449\u0435\u043D\u0438\u044F, \u0435\u0441\u043B\u0438 \u0431\u043E\u043B\u0435\u0435 \u0434\u043B\u0438\u0442\u0435\u043B\u044C\u043D\u044B\u0439 \u0441\u0440\u043E\u043A \u043D\u0435 \u0442\u0440\u0435\u0431\u0443\u0435\u0442\u0441\u044F \u043F\u043E \u0437\u0430\u043A\u043E\u043D\u0443.</li>\n      </ul>"},{"id":"section-9","title":"9. \u041F\u0440\u0430\u0432\u0430 \u0441\u0443\u0431\u044A\u0435\u043A\u0442\u0430 \u043F\u0435\u0440\u0441\u043E\u043D\u0430\u043B\u044C\u043D\u044B\u0445 \u0434\u0430\u043D\u043D\u044B\u0445","html":"<p>\u0421\u0443\u0431\u044A\u0435\u043A\u0442 \u043F\u0435\u0440\u0441\u043E\u043D\u0430\u043B\u044C\u043D\u044B\u0445 \u0434\u0430\u043D\u043D\u044B\u0445 \u0432\u043F\u0440\u0430\u0432\u0435:</p>\n      <ul>\n        <li>\u043F\u043E\u043B\u0443\u0447\u0430\u0442\u044C \u0441\u0432\u0435\u0434\u0435\u043D\u0438\u044F \u043E\u0431 \u043E\u0431\u0440\u0430\u0431\u043E\u0442\u043A\u0435 \u0441\u0432\u043E\u0438\u0445 \u043F\u0435\u0440\u0441\u043E\u043D\u0430\u043B\u044C\u043D\u044B\u0445 \u0434\u0430\u043D\u043D\u044B\u0445;</li>\n        <li>\u0442\u0440\u0435\u0431\u043E\u0432\u0430\u0442\u044C \u0443\u0442\u043E\u0447\u043D\u0435\u043D\u0438\u044F, \u0431\u043B\u043E\u043A\u0438\u0440\u043E\u0432\u0430\u043D\u0438\u044F \u0438\u043B\u0438 \u0443\u043D\u0438\u0447\u0442\u043E\u0436\u0435\u043D\u0438\u044F \u0434\u0430\u043D\u043D\u044B\u0445, \u0435\u0441\u043B\u0438 \u043E\u043D\u0438 \u043D\u0435\u043F\u043E\u043B\u043D\u044B\u0435, \u0443\u0441\u0442\u0430\u0440\u0435\u0432\u0448\u0438\u0435 \u0438\u043B\u0438 \u043E\u0431\u0440\u0430\u0431\u0430\u0442\u044B\u0432\u0430\u044E\u0442\u0441\u044F \u043D\u0435\u0437\u0430\u043A\u043E\u043D\u043D\u043E;</li>\n        <li>\u043E\u0442\u043E\u0437\u0432\u0430\u0442\u044C \u0441\u043E\u0433\u043B\u0430\u0441\u0438\u0435 \u043D\u0430 \u043E\u0431\u0440\u0430\u0431\u043E\u0442\u043A\u0443 \u043F\u0435\u0440\u0441\u043E\u043D\u0430\u043B\u044C\u043D\u044B\u0445 \u0434\u0430\u043D\u043D\u044B\u0445, \u043A\u043E\u0433\u0434\u0430 \u043E\u0431\u0440\u0430\u0431\u043E\u0442\u043A\u0430 \u043E\u0441\u043D\u043E\u0432\u0430\u043D\u0430 \u043D\u0430 \u0441\u043E\u0433\u043B\u0430\u0441\u0438\u0438;</li>\n        <li>\u0442\u0440\u0435\u0431\u043E\u0432\u0430\u0442\u044C \u043F\u0440\u0435\u043A\u0440\u0430\u0449\u0435\u043D\u0438\u044F \u0440\u0430\u0441\u043F\u0440\u043E\u0441\u0442\u0440\u0430\u043D\u0435\u043D\u0438\u044F \u0438\u043B\u0438 \u0441\u043A\u0440\u044B\u0442\u0438\u044F \u043F\u0443\u0431\u043B\u0438\u0447\u043D\u043E\u0433\u043E \u043F\u0440\u043E\u0444\u0438\u043B\u044F, \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442\u043E\u0432 \u0433\u043E\u043D\u043E\u043A \u0438 \u0438\u043D\u044B\u0445 \u0440\u0430\u0437\u043C\u0435\u0449\u0435\u043D\u043D\u044B\u0445 \u043D\u0430 \u0441\u0430\u0439\u0442\u0435 \u0434\u0430\u043D\u043D\u044B\u0445, \u0435\u0441\u043B\u0438 \u0434\u043B\u044F \u044D\u0442\u043E\u0433\u043E \u0438\u043C\u0435\u044E\u0442\u0441\u044F \u043E\u0441\u043D\u043E\u0432\u0430\u043D\u0438\u044F, \u043F\u0440\u0435\u0434\u0443\u0441\u043C\u043E\u0442\u0440\u0435\u043D\u043D\u044B\u0435 \u0437\u0430\u043A\u043E\u043D\u043E\u0434\u0430\u0442\u0435\u043B\u044C\u0441\u0442\u0432\u043E\u043C \u0420\u0424;</li>\n        <li>\u0438\u0437\u043C\u0435\u043D\u0438\u0442\u044C \u0440\u0435\u0448\u0435\u043D\u0438\u0435 \u043F\u043E \u0430\u043D\u0430\u043B\u0438\u0442\u0438\u043A\u0435 \u0447\u0435\u0440\u0435\u0437 \u043A\u043D\u043E\u043F\u043A\u0443 \xAB\u041D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438 cookies\xBB \u0432 \u0444\u0443\u0442\u0435\u0440\u0435 \u0441\u0430\u0439\u0442\u0430;</li>\n        <li>\u043E\u0431\u0440\u0430\u0442\u0438\u0442\u044C\u0441\u044F \u0432 \u0420\u043E\u0441\u043A\u043E\u043C\u043D\u0430\u0434\u0437\u043E\u0440 \u0438\u043B\u0438 \u0432 \u0441\u0443\u0434 \u0434\u043B\u044F \u0437\u0430\u0449\u0438\u0442\u044B \u0441\u0432\u043E\u0438\u0445 \u043F\u0440\u0430\u0432.</li>\n      </ul>"},{"id":"section-10","title":"10. \u041C\u0435\u0440\u044B \u043F\u043E \u0437\u0430\u0449\u0438\u0442\u0435 \u043F\u0435\u0440\u0441\u043E\u043D\u0430\u043B\u044C\u043D\u044B\u0445 \u0434\u0430\u043D\u043D\u044B\u0445","html":"<ul>\n        <li>\u043E\u0433\u0440\u0430\u043D\u0438\u0447\u0435\u043D\u0438\u0435 \u0441\u043E\u0441\u0442\u0430\u0432\u0430 \u0441\u043E\u0431\u0438\u0440\u0430\u0435\u043C\u044B\u0445 \u0434\u0430\u043D\u043D\u044B\u0445 \u0438 \u043E\u0442\u043A\u0430\u0437 \u043E\u0442 \u0437\u0430\u0433\u0440\u0443\u0437\u043A\u0438 \u0430\u043D\u0430\u043B\u0438\u0442\u0438\u043A\u0438 \u0431\u0435\u0437 \u043E\u0442\u0434\u0435\u043B\u044C\u043D\u043E\u0433\u043E \u0441\u043E\u0433\u043B\u0430\u0441\u0438\u044F;</li>\n        <li>\u0438\u0441\u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u043D\u0438\u0435 HTTPS \u0438 \u0442\u0435\u0445\u043D\u0438\u0447\u0435\u0441\u043A\u0438\u0445 \u043C\u0435\u0440 \u0437\u0430\u0449\u0438\u0442\u044B \u0434\u043E\u0441\u0442\u0443\u043F\u0430 \u043A \u0442\u043E\u043A\u0435\u043D\u0430\u043C \u0438 \u0430\u0434\u043C\u0438\u043D\u0438\u0441\u0442\u0440\u0430\u0442\u0438\u0432\u043D\u043E\u0439 \u0438\u043D\u0444\u0440\u0430\u0441\u0442\u0440\u0443\u043A\u0442\u0443\u0440\u0435;</li>\n        <li>\u0440\u0430\u0437\u0433\u0440\u0430\u043D\u0438\u0447\u0435\u043D\u0438\u0435 \u0434\u043E\u0441\u0442\u0443\u043F\u0430 \u043A \u0434\u0430\u043D\u043D\u044B\u043C \u0438 \u0430\u0434\u043C\u0438\u043D\u0438\u0441\u0442\u0440\u0430\u0442\u0438\u0432\u043D\u044B\u043C \u0443\u0447\u0451\u0442\u043D\u044B\u043C \u0437\u0430\u043F\u0438\u0441\u044F\u043C;</li>\n        <li>\u043F\u0435\u0440\u0438\u043E\u0434\u0438\u0447\u0435\u0441\u043A\u0438\u0439 \u043F\u0435\u0440\u0435\u0441\u043C\u043E\u0442\u0440 \u0441\u043E\u0441\u0442\u0430\u0432\u0430 \u043F\u0443\u0431\u043B\u0438\u043A\u0443\u0435\u043C\u044B\u0445 \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442\u043E\u0432, \u043F\u0440\u043E\u0444\u0438\u043B\u0435\u0439 \u0443\u0447\u0430\u0441\u0442\u043D\u0438\u043A\u043E\u0432 \u0438 \u0432\u043D\u0435\u0448\u043D\u0438\u0445 \u0441\u0435\u0440\u0432\u0438\u0441\u043E\u0432, \u0438\u043C\u0435\u044E\u0449\u0438\u0445 \u0434\u043E\u0441\u0442\u0443\u043F \u043A \u0434\u0430\u043D\u043D\u044B\u043C;</li>\n        <li>\u043F\u0435\u0440\u0438\u043E\u0434\u0438\u0447\u0435\u0441\u043A\u0438\u0439 \u043F\u0435\u0440\u0435\u0441\u043C\u043E\u0442\u0440 \u043D\u0430\u0441\u0442\u0440\u043E\u0435\u043A \u0430\u043D\u0430\u043B\u0438\u0442\u0438\u043A\u0438, cookie \u0438 \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u0443\u0435\u043C\u044B\u0445 \u0432\u043D\u0435\u0448\u043D\u0438\u0445 \u0441\u0435\u0440\u0432\u0438\u0441\u043E\u0432.</li>\n      </ul>"},{"id":"section-11","title":"11. \u041E\u0431\u0440\u0430\u0449\u0435\u043D\u0438\u044F \u0438 \u0443\u0432\u0435\u0434\u043E\u043C\u043B\u0435\u043D\u0438\u044F","html":"<p>\n        \u0417\u0430\u043F\u0440\u043E\u0441\u044B \u043F\u043E \u0432\u043E\u043F\u0440\u043E\u0441\u0430\u043C \u043E\u0431\u0440\u0430\u0431\u043E\u0442\u043A\u0438 \u043F\u0435\u0440\u0441\u043E\u043D\u0430\u043B\u044C\u043D\u044B\u0445 \u0434\u0430\u043D\u043D\u044B\u0445 \u043D\u0430\u043F\u0440\u0430\u0432\u043B\u044F\u044E\u0442\u0441\u044F \u043E\u043F\u0435\u0440\u0430\u0442\u043E\u0440\u0443 \u043F\u043E \u0430\u0434\u0440\u0435\u0441\u0443:\n        <code>itriahon@gmail.com</code>.\n      </p>\n      <p>\n        \u041F\u043E \u0443\u043A\u0430\u0437\u0430\u043D\u043D\u043E\u043C\u0443 \u0430\u0434\u0440\u0435\u0441\u0443 \u043C\u043E\u0436\u043D\u043E \u043D\u0430\u043F\u0440\u0430\u0432\u0438\u0442\u044C \u0437\u0430\u043F\u0440\u043E\u0441 \u043D\u0430 \u043F\u0440\u0435\u0434\u043E\u0441\u0442\u0430\u0432\u043B\u0435\u043D\u0438\u0435 \u0441\u0432\u0435\u0434\u0435\u043D\u0438\u0439 \u043E\u0431 \u043E\u0431\u0440\u0430\u0431\u043E\u0442\u043A\u0435 \u043F\u0435\u0440\u0441\u043E\u043D\u0430\u043B\u044C\u043D\u044B\u0445\n        \u0434\u0430\u043D\u043D\u044B\u0445, \u0443\u0442\u043E\u0447\u043D\u0435\u043D\u0438\u0435 \u0434\u0430\u043D\u043D\u044B\u0445, \u0443\u0434\u0430\u043B\u0435\u043D\u0438\u0435 \u0434\u0430\u043D\u043D\u044B\u0445, \u043F\u0440\u0435\u043A\u0440\u0430\u0449\u0435\u043D\u0438\u0435 \u0440\u0430\u0441\u043F\u0440\u043E\u0441\u0442\u0440\u0430\u043D\u0435\u043D\u0438\u044F \u043F\u0443\u0431\u043B\u0438\u0447\u043D\u043E\u0433\u043E \u043F\u0440\u043E\u0444\u0438\u043B\u044F \u0438\u043B\u0438\n        \u043E\u0433\u0440\u0430\u043D\u0438\u0447\u0435\u043D\u0438\u0435 \u043F\u0443\u0431\u043B\u0438\u043A\u0430\u0446\u0438\u0438 \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442\u043E\u0432 \u0433\u043E\u043D\u043E\u043A, \u0435\u0441\u043B\u0438 \u0437\u0430\u043F\u0440\u043E\u0441 \u043E\u0442\u043D\u043E\u0441\u0438\u0442\u0441\u044F \u043A \u0441\u0443\u0431\u044A\u0435\u043A\u0442\u0443 \u043F\u0435\u0440\u0441\u043E\u043D\u0430\u043B\u044C\u043D\u044B\u0445 \u0434\u0430\u043D\u043D\u044B\u0445.\n      </p>\n      <p>\n        \u041E\u043F\u0435\u0440\u0430\u0442\u043E\u0440 \u0440\u0430\u0441\u0441\u043C\u0430\u0442\u0440\u0438\u0432\u0430\u0435\u0442 \u043E\u0431\u0440\u0430\u0449\u0435\u043D\u0438\u044F \u0441\u0443\u0431\u044A\u0435\u043A\u0442\u043E\u0432 \u043F\u0435\u0440\u0441\u043E\u043D\u0430\u043B\u044C\u043D\u044B\u0445 \u0434\u0430\u043D\u043D\u044B\u0445 \u0432 \u0441\u0440\u043E\u043A\u0438, \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D\u043D\u044B\u0435\n        \u0437\u0430\u043A\u043E\u043D\u043E\u0434\u0430\u0442\u0435\u043B\u044C\u0441\u0442\u0432\u043E\u043C \u0420\u0424, \u043A\u0430\u043A \u043F\u0440\u0430\u0432\u0438\u043B\u043E \u043D\u0435 \u043F\u043E\u0437\u0434\u043D\u0435\u0435 10 \u0440\u0430\u0431\u043E\u0447\u0438\u0445 \u0434\u043D\u0435\u0439 \u0441 \u0434\u0430\u0442\u044B \u043F\u043E\u043B\u0443\u0447\u0435\u043D\u0438\u044F \u0437\u0430\u043F\u0440\u043E\u0441\u0430, \u0441 \u0432\u043E\u0437\u043C\u043E\u0436\u043D\u044B\u043C\n        \u043F\u0440\u043E\u0434\u043B\u0435\u043D\u0438\u0435\u043C \u0441\u0440\u043E\u043A\u0430 \u0432 \u0441\u043B\u0443\u0447\u0430\u044F\u0445, \u043F\u0440\u044F\u043C\u043E \u043F\u0440\u0435\u0434\u0443\u0441\u043C\u043E\u0442\u0440\u0435\u043D\u043D\u044B\u0445 \u0437\u0430\u043A\u043E\u043D\u043E\u043C.\n      </p>\n      <p>\n        \u041E\u043F\u0435\u0440\u0430\u0442\u043E\u0440 \u043E\u0431\u044F\u0437\u0430\u043D \u043F\u043E\u0434\u0434\u0435\u0440\u0436\u0438\u0432\u0430\u0442\u044C \u0430\u043A\u0442\u0443\u0430\u043B\u044C\u043D\u043E\u0441\u0442\u044C \u0441\u0432\u0435\u0434\u0435\u043D\u0438\u0439 \u0432 \u0443\u0432\u0435\u0434\u043E\u043C\u043B\u0435\u043D\u0438\u0438 \u043E\u0431 \u043E\u0431\u0440\u0430\u0431\u043E\u0442\u043A\u0435 \u043F\u0435\u0440\u0441\u043E\u043D\u0430\u043B\u044C\u043D\u044B\u0445 \u0434\u0430\u043D\u043D\u044B\u0445,\n        \u043F\u043E\u0434\u0430\u043D\u043D\u043E\u043C \u0432 \u0420\u043E\u0441\u043A\u043E\u043C\u043D\u0430\u0434\u0437\u043E\u0440, \u0430 \u0442\u0430\u043A\u0436\u0435 \u043F\u0440\u0438 \u043D\u0430\u043B\u0438\u0447\u0438\u0438 \u043E\u0441\u043D\u043E\u0432\u0430\u043D\u0438\u0439 \u043E\u0442\u0434\u0435\u043B\u044C\u043D\u043E \u043E\u0446\u0435\u043D\u0438\u0432\u0430\u0442\u044C \u0438 \u043E\u0444\u043E\u0440\u043C\u043B\u044F\u0442\u044C \u0443\u0432\u0435\u0434\u043E\u043C\u043B\u0435\u043D\u0438\u044F,\n        \u0441\u0432\u044F\u0437\u0430\u043D\u043D\u044B\u0435 \u0441 \u0442\u0440\u0430\u043D\u0441\u0433\u0440\u0430\u043D\u0438\u0447\u043D\u043E\u0439 \u043F\u0435\u0440\u0435\u0434\u0430\u0447\u0435\u0439 \u043F\u0435\u0440\u0441\u043E\u043D\u0430\u043B\u044C\u043D\u044B\u0445 \u0434\u0430\u043D\u043D\u044B\u0445.\n      </p>"},{"id":"section-12","title":"English Note","html":"<p>\n        This page is the main privacy policy for ASG Racing under Russian personal data law. The Russian\n        text prevails. Yandex Metrica is loaded only after analytics consent, and Google Analytics is not in\n        use as of April 30, 2026.\n      </p>"}],"source":"/privacy/","official_language":"ru"},"cookies":{"title":"\u0423\u0432\u0435\u0434\u043E\u043C\u043B\u0435\u043D\u0438\u0435 \u043E\u0431 \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u043D\u0438\u0438 cookies, localStorage \u0438 \u0430\u043D\u0430\u043B\u0438\u0442\u0438\u043A\u0438","intro_html":'<header class="legal-header">\n      <div class="legal-kicker">ASG Racing</div>\n      <h2>\u0423\u0432\u0435\u0434\u043E\u043C\u043B\u0435\u043D\u0438\u0435 \u043E\u0431 \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u043D\u0438\u0438 cookies, localStorage \u0438 \u0430\u043D\u0430\u043B\u0438\u0442\u0438\u043A\u0438</h2>\n      <p class="legal-updated">\u0414\u0430\u0442\u0430 \u043E\u0431\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u044F: 30.04.2026</p>\n    </header>',"sections":[{"id":"section-1","title":"\u0412\u0432\u0435\u0434\u0435\u043D\u0438\u0435","html":'<p>\n        \u041E\u043F\u0435\u0440\u0430\u0442\u043E\u0440 \u0441\u0430\u0439\u0442\u0430: \u041E\u043D\u043B\u0430\u0439\u043D \u0441\u043E\u043E\u0431\u0449\u0435\u0441\u0442\u0432\u043E ASG Racing. \u0412\u043E\u043F\u0440\u043E\u0441\u044B \u043F\u043E \u043E\u0431\u0440\u0430\u0431\u043E\u0442\u043A\u0435 \u043F\u0435\u0440\u0441\u043E\u043D\u0430\u043B\u044C\u043D\u044B\u0445 \u0434\u0430\u043D\u043D\u044B\u0445, \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0430\u043C\n        \u0430\u043D\u0430\u043B\u0438\u0442\u0438\u043A\u0438 \u0438 \u0440\u0430\u0431\u043E\u0442\u0435 cookie \u043C\u043E\u0436\u043D\u043E \u043D\u0430\u043F\u0440\u0430\u0432\u043B\u044F\u0442\u044C \u043D\u0430 <code>itriahon@gmail.com</code>. \u041F\u043E\u043B\u043D\u0430\u044F \u0438\u043D\u0444\u043E\u0440\u043C\u0430\u0446\u0438\u044F \u043E\n        \u0441\u043E\u0441\u0442\u0430\u0432\u0435 \u0438 \u0446\u0435\u043B\u044F\u0445 \u043E\u0431\u0440\u0430\u0431\u043E\u0442\u043A\u0438 \u043F\u0435\u0440\u0441\u043E\u043D\u0430\u043B\u044C\u043D\u044B\u0445 \u0434\u0430\u043D\u043D\u044B\u0445 \u043F\u0440\u0438\u0432\u0435\u0434\u0435\u043D\u0430 \u0432 <a href="/privacy/">\u043F\u043E\u043B\u0438\u0442\u0438\u043A\u0435 \u043E\u0431\u0440\u0430\u0431\u043E\u0442\u043A\u0438 \u043F\u0435\u0440\u0441\u043E\u043D\u0430\u043B\u044C\u043D\u044B\u0445 \u0434\u0430\u043D\u043D\u044B\u0445</a>.\n      </p>'},{"id":"section-2","title":"1. \u0427\u0442\u043E \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u0443\u0435\u0442 \u0441\u0430\u0439\u0442","html":"<p>\u0421\u0430\u0439\u0442 ASG Racing \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u0443\u0435\u0442:</p>\n      <ul>\n        <li>\u043E\u0431\u044F\u0437\u0430\u0442\u0435\u043B\u044C\u043D\u044B\u0435 \u0438 \u0444\u0443\u043D\u043A\u0446\u0438\u043E\u043D\u0430\u043B\u044C\u043D\u044B\u0435 cookie/localStorage \u0434\u043B\u044F \u0440\u0430\u0431\u043E\u0442\u044B \u0438\u043D\u0442\u0435\u0440\u0444\u0435\u0439\u0441\u0430;</li>\n        <li>\u0430\u043D\u0430\u043B\u0438\u0442\u0438\u0447\u0435\u0441\u043A\u0438\u0435 cookie \u0438 localStorage \u042F\u043D\u0434\u0435\u043A\u0441 \u041C\u0435\u0442\u0440\u0438\u043A\u0438 \u2014 \u0442\u043E\u043B\u044C\u043A\u043E \u043F\u043E\u0441\u043B\u0435 \u0441\u043E\u0433\u043B\u0430\u0441\u0438\u044F \u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u0435\u043B\u044F;</li>\n        <li>\u0442\u0435\u0445\u043D\u0438\u0447\u0435\u0441\u043A\u0438\u0439 localStorage-\u0438\u0434\u0435\u043D\u0442\u0438\u0444\u0438\u043A\u0430\u0442\u043E\u0440 \u0434\u043B\u044F \u0433\u043E\u043B\u043E\u0441\u043E\u0432\u0430\u043D\u0438\u044F \u0437\u0430 \u0441\u043B\u043E\u0442 \u0447\u0430\u0441\u043E\u0432\u043E\u0439 \u0433\u043E\u043D\u043A\u0438.</li>\n      </ul>\n      <p>\n        \u041F\u043E \u0441\u043E\u0441\u0442\u043E\u044F\u043D\u0438\u044E \u043D\u0430 30.04.2026 Google Analytics \u043D\u0435 \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u0443\u0435\u0442\u0441\u044F. \u0415\u0441\u043B\u0438 \u0432 \u0431\u0443\u0434\u0443\u0449\u0435\u043C \u043F\u0440\u043E\u0435\u043A\u0442 \u043F\u043E\u0434\u043A\u043B\u044E\u0447\u0438\u0442 \u043D\u043E\u0432\u0443\u044E\n        \u0441\u0438\u0441\u0442\u0435\u043C\u0443 \u0430\u043D\u0430\u043B\u0438\u0442\u0438\u043A\u0438, \u043D\u0430\u0441\u0442\u043E\u044F\u0449\u0435\u0435 \u0443\u0432\u0435\u0434\u043E\u043C\u043B\u0435\u043D\u0438\u0435 \u0434\u043E\u043B\u0436\u043D\u043E \u0431\u044B\u0442\u044C \u043E\u0431\u043D\u043E\u0432\u043B\u0435\u043D\u043E \u0434\u043E \u043D\u0430\u0447\u0430\u043B\u0430 \u0435\u0451 \u0437\u0430\u0433\u0440\u0443\u0437\u043A\u0438.\n      </p>"},{"id":"section-3","title":"2. \u041E\u0431\u044F\u0437\u0430\u0442\u0435\u043B\u044C\u043D\u044B\u0435 \u0438 \u0444\u0443\u043D\u043A\u0446\u0438\u043E\u043D\u0430\u043B\u044C\u043D\u044B\u0435 \u0434\u0430\u043D\u043D\u044B\u0435 \u0432 \u0431\u0440\u0430\u0443\u0437\u0435\u0440\u0435","html":'<div class="legal-table-wrap">\n        <table class="legal-table">\n          <thead>\n            <tr>\n              <th>\u041A\u043B\u044E\u0447</th>\n              <th>\u041D\u0430\u0437\u043D\u0430\u0447\u0435\u043D\u0438\u0435</th>\n              <th>\u0421\u0440\u043E\u043A</th>\n            </tr>\n          </thead>\n          <tbody>\n            <tr>\n              <td><code>asgPrivacyConsent</code></td>\n              <td>\u0417\u0430\u043F\u043E\u043C\u0438\u043D\u0430\u0435\u0442 \u0432\u044B\u0431\u043E\u0440 \u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u0435\u043B\u044F \u043F\u043E \u0430\u043D\u0430\u043B\u0438\u0442\u0438\u043A\u0435</td>\n              <td>\u0414\u043E \u0438\u0437\u043C\u0435\u043D\u0435\u043D\u0438\u044F \u0432\u044B\u0431\u043E\u0440\u0430 \u0438\u043B\u0438 \u043E\u0431\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u044F \u0432\u0435\u0440\u0441\u0438\u0438 \u0441\u043E\u0433\u043B\u0430\u0441\u0438\u044F</td>\n            </tr>\n            <tr>\n              <td><code>asgLang</code></td>\n              <td>\u0425\u0440\u0430\u043D\u0438\u0442 \u0432\u044B\u0431\u0440\u0430\u043D\u043D\u044B\u0439 \u044F\u0437\u044B\u043A \u0438\u043D\u0442\u0435\u0440\u0444\u0435\u0439\u0441\u0430</td>\n              <td>\u0414\u043E \u043E\u0447\u0438\u0441\u0442\u043A\u0438 \u0431\u0440\u0430\u0443\u0437\u0435\u0440\u0430 \u0438\u043B\u0438 \u0441\u043C\u0435\u043D\u044B \u044F\u0437\u044B\u043A\u0430</td>\n            </tr>\n            <tr>\n              <td><code>asgLocale</code></td>\n              <td>\u0425\u0440\u0430\u043D\u0438\u0442 \u044F\u0432\u043D\u043E \u0432\u044B\u0431\u0440\u0430\u043D\u043D\u044B\u0435 \u044F\u0437\u044B\u043A \u0438 \u0440\u0435\u0433\u0438\u043E\u043D \u0441\u0430\u0439\u0442\u0430; \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u0443\u0435\u0442\u0441\u044F \u0441\u043E\u0432\u043C\u0435\u0441\u0442\u043D\u043E \u0441 <code>asgLang</code> \u0434\u043B\u044F \u0441\u043E\u0432\u043C\u0435\u0441\u0442\u0438\u043C\u043E\u0441\u0442\u0438</td>\n              <td>\u0414\u043E \u043E\u0447\u0438\u0441\u0442\u043A\u0438 \u0431\u0440\u0430\u0443\u0437\u0435\u0440\u0430 \u0438\u043B\u0438 \u0441\u043C\u0435\u043D\u044B \u044F\u0437\u044B\u043A\u0430</td>\n            </tr>\n            <tr>\n              <td><code>asgLocaleSuggestionDismissed</code></td>\n              <td>\u0417\u0430\u043F\u043E\u043C\u0438\u043D\u0430\u0435\u0442 \u0437\u0430\u043A\u0440\u044B\u0442\u0438\u0435 \u043F\u0440\u0435\u0434\u043B\u043E\u0436\u0435\u043D\u0438\u044F \u043F\u0435\u0440\u0435\u0439\u0442\u0438 \u043D\u0430 \u044F\u0437\u044B\u043A, \u043E\u043F\u0440\u0435\u0434\u0435\u043B\u0451\u043D\u043D\u044B\u0439 \u043F\u043E \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0430\u043C \u0431\u0440\u0430\u0443\u0437\u0435\u0440\u0430 \u0438 \u0447\u0430\u0441\u043E\u0432\u043E\u043C\u0443 \u043F\u043E\u044F\u0441\u0443</td>\n              <td>\u0414\u043E \u043E\u0447\u0438\u0441\u0442\u043A\u0438 \u0431\u0440\u0430\u0443\u0437\u0435\u0440\u0430 \u0438\u043B\u0438 \u044F\u0432\u043D\u043E\u0439 \u0441\u043C\u0435\u043D\u044B \u044F\u0437\u044B\u043A\u0430</td>\n            </tr>\n            <tr>\n              <td><code>hourlyVoteVoterId</code></td>\n              <td>\u0421\u043B\u0443\u0447\u0430\u0439\u043D\u044B\u0439 \u0442\u0435\u0445\u043D\u0438\u0447\u0435\u0441\u043A\u0438\u0439 \u0438\u0434\u0435\u043D\u0442\u0438\u0444\u0438\u043A\u0430\u0442\u043E\u0440 \u0431\u0440\u0430\u0443\u0437\u0435\u0440\u0430 \u0434\u043B\u044F \u043E\u0433\u0440\u0430\u043D\u0438\u0447\u0435\u043D\u0438\u044F \u043E\u0434\u043D\u0438\u043C \u0433\u043E\u043B\u043E\u0441\u043E\u043C \u043D\u0430 \u0441\u043B\u043E\u0442</td>\n              <td>\u0414\u043E 12 \u043C\u0435\u0441\u044F\u0446\u0435\u0432 \u0438\u043B\u0438 \u0434\u043E \u043E\u0447\u0438\u0441\u0442\u043A\u0438 \u0431\u0440\u0430\u0443\u0437\u0435\u0440\u0430</td>\n            </tr>\n            <tr>\n              <td><code>asgTopGuideSeen</code></td>\n              <td>\u0417\u0430\u043F\u043E\u043C\u0438\u043D\u0430\u0435\u0442 \u0437\u0430\u043A\u0440\u044B\u0442\u0438\u0435 \u043E\u0431\u0443\u0447\u0430\u044E\u0449\u0435\u0439 \u043F\u043E\u0434\u0441\u043A\u0430\u0437\u043A\u0438 \u043D\u0430 \u0433\u043B\u0430\u0432\u043D\u043E\u0439 \u0441\u0442\u0440\u0430\u043D\u0438\u0446\u0435</td>\n              <td>\u0414\u043E \u043E\u0447\u0438\u0441\u0442\u043A\u0438 \u0431\u0440\u0430\u0443\u0437\u0435\u0440\u0430</td>\n            </tr>\n          </tbody>\n        </table>\n      </div>'},{"id":"section-4","title":"3. \u0410\u043D\u0430\u043B\u0438\u0442\u0438\u043A\u0430 \u042F\u043D\u0434\u0435\u043A\u0441 \u041C\u0435\u0442\u0440\u0438\u043A\u0438","html":'<p>\n        \u041F\u043E\u0441\u043B\u0435 \u043F\u043E\u043B\u0443\u0447\u0435\u043D\u0438\u044F \u0441\u043E\u0433\u043B\u0430\u0441\u0438\u044F \u0441\u0430\u0439\u0442 \u043C\u043E\u0436\u0435\u0442 \u0437\u0430\u0433\u0440\u0443\u0436\u0430\u0442\u044C \u0441\u0447\u0451\u0442\u0447\u0438\u043A \u042F\u043D\u0434\u0435\u043A\u0441 \u041C\u0435\u0442\u0440\u0438\u043A\u0438. \u0421\u043E\u0433\u043B\u0430\u0441\u043D\u043E \u0434\u043E\u043A\u0443\u043C\u0435\u043D\u0442\u0430\u0446\u0438\u0438 \u042F\u043D\u0434\u0435\u043A\u0441\n        \u041C\u0435\u0442\u0440\u0438\u043A\u0438, \u0441\u0435\u0440\u0432\u0438\u0441 \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u0443\u0435\u0442 cookie \u0438 localStorage-\u0441\u0432\u043E\u0439\u0441\u0442\u0432\u0430 \u0434\u043B\u044F \u0443\u0447\u0451\u0442\u0430 \u043F\u043E\u0441\u0435\u0449\u0435\u043D\u0438\u0439 \u0438 \u0440\u0430\u0437\u043B\u0438\u0447\u0435\u043D\u0438\u044F\n        \u0431\u0440\u0430\u0443\u0437\u0435\u0440\u043E\u0432.\n      </p>\n      <div class="legal-table-wrap">\n        <table class="legal-table">\n          <thead>\n            <tr>\n              <th>\u041F\u0440\u0438\u043C\u0435\u0440 \u0438\u043C\u0435\u043D\u0438</th>\n              <th>\u041D\u0430\u0437\u043D\u0430\u0447\u0435\u043D\u0438\u0435</th>\n              <th>\u0421\u0440\u043E\u043A \u0438\u0437 \u0434\u043E\u043A\u0443\u043C\u0435\u043D\u0442\u0430\u0446\u0438\u0438 \u042F\u043D\u0434\u0435\u043A\u0441</th>\n            </tr>\n          </thead>\n          <tbody>\n            <tr>\n              <td><code>_ym_metrika_enabled</code></td>\n              <td>\u041F\u0440\u043E\u0432\u0435\u0440\u043A\u0430 \u043A\u043E\u0440\u0440\u0435\u043A\u0442\u043D\u043E\u0441\u0442\u0438 \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043A\u0438 cookies \u041C\u0435\u0442\u0440\u0438\u043A\u0438</td>\n              <td>60 \u043C\u0438\u043D\u0443\u0442</td>\n            </tr>\n            <tr>\n              <td><code>_ym_isad</code></td>\n              <td>\u041E\u043F\u0440\u0435\u0434\u0435\u043B\u0435\u043D\u0438\u0435 \u043D\u0430\u043B\u0438\u0447\u0438\u044F \u0431\u043B\u043E\u043A\u0438\u0440\u043E\u0432\u0449\u0438\u043A\u043E\u0432 \u0440\u0435\u043A\u043B\u0430\u043C\u044B</td>\n              <td>20 \u0447\u0430\u0441\u043E\u0432</td>\n            </tr>\n            <tr>\n              <td><code>_ym_uid</code></td>\n              <td>\u0420\u0430\u0437\u043B\u0438\u0447\u0435\u043D\u0438\u0435 \u043F\u043E\u0441\u0435\u0442\u0438\u0442\u0435\u043B\u0435\u0439</td>\n              <td>1 \u0433\u043E\u0434</td>\n            </tr>\n            <tr>\n              <td><code>_ym_fa</code></td>\n              <td>\u0421\u043B\u0443\u0436\u0435\u0431\u043D\u0430\u044F \u0438\u0434\u0435\u043D\u0442\u0438\u0444\u0438\u043A\u0430\u0446\u0438\u044F \u043F\u043E\u0441\u0435\u0442\u0438\u0442\u0435\u043B\u044F</td>\n              <td>\u041E\u043F\u0440\u0435\u0434\u0435\u043B\u044F\u0435\u0442\u0441\u044F \u0441\u0435\u0440\u0432\u0438\u0441\u043E\u043C</td>\n            </tr>\n            <tr>\n              <td><code>_ym_d</code></td>\n              <td>\u0414\u0430\u0442\u0430 \u043F\u0435\u0440\u0432\u043E\u0433\u043E \u0432\u0438\u0437\u0438\u0442\u0430</td>\n              <td>\u041E\u043F\u0440\u0435\u0434\u0435\u043B\u044F\u0435\u0442\u0441\u044F \u0441\u0435\u0440\u0432\u0438\u0441\u043E\u043C</td>\n            </tr>\n            <tr>\n              <td><code>_ym_visorc_*</code></td>\n              <td>\u0422\u0435\u0445\u043D\u0438\u0447\u0435\u0441\u043A\u0430\u044F \u0440\u0430\u0431\u043E\u0442\u0430 \u0412\u0435\u0431\u0432\u0438\u0437\u043E\u0440\u0430</td>\n              <td>30 \u043C\u0438\u043D\u0443\u0442</td>\n            </tr>\n            <tr>\n              <td><code>localStorage-\u0441\u0432\u043E\u0439\u0441\u0442\u0432\u0430 \u041C\u0435\u0442\u0440\u0438\u043A\u0438</code></td>\n              <td>\u0421\u043B\u0443\u0436\u0435\u0431\u043D\u0430\u044F \u0430\u043D\u0430\u043B\u0438\u0442\u0438\u043A\u0430 \u0438 \u0438\u0434\u0435\u043D\u0442\u0438\u0444\u0438\u043A\u0430\u0442\u043E\u0440\u044B \u0431\u0440\u0430\u0443\u0437\u0435\u0440\u0430</td>\n              <td>\u041F\u043E \u043F\u0440\u0430\u0432\u0438\u043B\u0430\u043C \u0441\u0435\u0440\u0432\u0438\u0441\u0430</td>\n            </tr>\n          </tbody>\n        </table>\n      </div>\n      <p class="legal-note">\n        \u041F\u043E\u043B\u043D\u044B\u0439 \u043D\u0430\u0431\u043E\u0440 cookie \u041C\u0435\u0442\u0440\u0438\u043A\u0438 \u043C\u043E\u0436\u0435\u0442 \u043C\u0435\u043D\u044F\u0442\u044C\u0441\u044F \u0441\u043E \u0441\u0442\u043E\u0440\u043E\u043D\u044B \u0441\u0435\u0440\u0432\u0438\u0441\u0430. \u0410\u043A\u0442\u0443\u0430\u043B\u044C\u043D\u044B\u0439 \u043F\u0435\u0440\u0435\u0447\u0435\u043D\u044C \u0438 \u0441\u0440\u043E\u043A\u0438 \u0445\u0440\u0430\u043D\u0435\u043D\u0438\u044F\n        \u042F\u043D\u0434\u0435\u043A\u0441 \u043F\u0443\u0431\u043B\u0438\u043A\u0443\u0435\u0442 \u0432 \u0441\u0432\u043E\u0435\u0439 \u0434\u043E\u043A\u0443\u043C\u0435\u043D\u0442\u0430\u0446\u0438\u0438.\n      </p>'},{"id":"section-5","title":"4. \u041A\u0430\u043A \u0441\u0430\u0439\u0442 \u043F\u043E\u043B\u0443\u0447\u0430\u0435\u0442 \u0441\u043E\u0433\u043B\u0430\u0441\u0438\u0435","html":"<ul>\n        <li>\u043F\u0440\u0438 \u043F\u0435\u0440\u0432\u043E\u043C \u043F\u043E\u0441\u0435\u0449\u0435\u043D\u0438\u0438 \u0432\u044B\u0432\u043E\u0434\u0438\u0442\u0441\u044F \u0431\u0430\u043D\u043D\u0435\u0440 \u0441 \u0432\u044B\u0431\u043E\u0440\u043E\u043C: \u0440\u0430\u0437\u0440\u0435\u0448\u0438\u0442\u044C \u0430\u043D\u0430\u043B\u0438\u0442\u0438\u043A\u0443 \u0438\u043B\u0438 \u043E\u0441\u0442\u0430\u0432\u0438\u0442\u044C \u0442\u043E\u043B\u044C\u043A\u043E \u043D\u0435\u043E\u0431\u0445\u043E\u0434\u0438\u043C\u044B\u0435 \u0434\u0430\u043D\u043D\u044B\u0435;</li>\n        <li>\u0431\u0435\u0437 \u0441\u043E\u0433\u043B\u0430\u0441\u0438\u044F \u043A\u043E\u0434 \u042F\u043D\u0434\u0435\u043A\u0441 \u041C\u0435\u0442\u0440\u0438\u043A\u0438 \u043D\u0435 \u0437\u0430\u0433\u0440\u0443\u0436\u0430\u0435\u0442\u0441\u044F;</li>\n        <li>\u0438\u0437\u043C\u0435\u043D\u0438\u0442\u044C \u0440\u0435\u0448\u0435\u043D\u0438\u0435 \u043C\u043E\u0436\u043D\u043E \u0447\u0435\u0440\u0435\u0437 \u043A\u043D\u043E\u043F\u043A\u0443 \xAB\u041D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438 cookies\xBB \u0432 \u0444\u0443\u0442\u0435\u0440\u0435 \u0441\u0430\u0439\u0442\u0430;</li>\n        <li>\u043F\u0440\u0438 \u043E\u0442\u043A\u0430\u0437\u0435 \u043E\u0442 \u0430\u043D\u0430\u043B\u0438\u0442\u0438\u043A\u0438 \u0441\u0430\u0439\u0442 \u043F\u044B\u0442\u0430\u0435\u0442\u0441\u044F \u0443\u0434\u0430\u043B\u0438\u0442\u044C \u0443\u0436\u0435 \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D\u043D\u044B\u0435 cookie \u0438 localStorage \u042F\u043D\u0434\u0435\u043A\u0441 \u041C\u0435\u0442\u0440\u0438\u043A\u0438.</li>\n      </ul>"},{"id":"section-6","title":"5. \u0413\u043E\u043B\u043E\u0441\u043E\u0432\u0430\u043D\u0438\u0435 \u0437\u0430 \u0441\u043B\u043E\u0442 \u0447\u0430\u0441\u043E\u0432\u043E\u0439 \u0433\u043E\u043D\u043A\u0438","html":"<p>\n        \u041F\u0440\u0438 \u043D\u0430\u0436\u0430\u0442\u0438\u0438 \u043A\u043D\u043E\u043F\u043A\u0438 \u0433\u043E\u043B\u043E\u0441\u043E\u0432\u0430\u043D\u0438\u044F \u0441\u0430\u0439\u0442 \u0441\u043E\u0437\u0434\u0430\u0451\u0442 \u0441\u043B\u0443\u0447\u0430\u0439\u043D\u044B\u0439 \u0431\u0440\u0430\u0443\u0437\u0435\u0440\u043D\u044B\u0439 \u0438\u0434\u0435\u043D\u0442\u0438\u0444\u0438\u043A\u0430\u0442\u043E\u0440 \u0438 \u043E\u0442\u043F\u0440\u0430\u0432\u043B\u044F\u0435\u0442 \u0435\u0433\u043E \u0432\u043C\u0435\u0441\u0442\u0435\n        \u0441 \u0438\u0434\u0435\u043D\u0442\u0438\u0444\u0438\u043A\u0430\u0442\u043E\u0440\u043E\u043C \u0432\u044B\u0431\u0440\u0430\u043D\u043D\u043E\u0433\u043E \u0441\u043B\u043E\u0442\u0430 \u0432 API \u0433\u043E\u043B\u043E\u0441\u043E\u0432\u0430\u043D\u0438\u044F. \u042D\u0442\u043E \u043D\u0435\u043E\u0431\u0445\u043E\u0434\u0438\u043C\u043E \u0434\u043B\u044F \u0443\u0447\u0451\u0442\u0430 \u043E\u0434\u043D\u043E\u0433\u043E \u0433\u043E\u043B\u043E\u0441\u0430 \u043D\u0430 \u0441\u043B\u043E\u0442 \u0438\n        \u043F\u0440\u0435\u0434\u043E\u0442\u0432\u0440\u0430\u0449\u0435\u043D\u0438\u044F \u043F\u043E\u0432\u0442\u043E\u0440\u043D\u043E\u0433\u043E \u0433\u043E\u043B\u043E\u0441\u043E\u0432\u0430\u043D\u0438\u044F \u0438\u0437 \u0442\u043E\u0433\u043E \u0436\u0435 \u0431\u0440\u0430\u0443\u0437\u0435\u0440\u0430.\n      </p>\n      <p>\n        \u0415\u0441\u043B\u0438 \u0432\u044B \u043D\u0435 \u0445\u043E\u0442\u0438\u0442\u0435, \u0447\u0442\u043E\u0431\u044B \u0442\u0430\u043A\u043E\u0439 \u0438\u0434\u0435\u043D\u0442\u0438\u0444\u0438\u043A\u0430\u0442\u043E\u0440 \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u043B\u0441\u044F, \u043D\u0435 \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u0443\u0439\u0442\u0435 \u0444\u0443\u043D\u043A\u0446\u0438\u044E \u0433\u043E\u043B\u043E\u0441\u043E\u0432\u0430\u043D\u0438\u044F \u0438\n        \u043E\u0447\u0438\u0441\u0442\u0438\u0442\u0435 localStorage \u0431\u0440\u0430\u0443\u0437\u0435\u0440\u0430.\n      </p>"},{"id":"section-7","title":"6. \u041A\u0430\u043A \u043E\u0442\u043A\u043B\u044E\u0447\u0438\u0442\u044C cookies \u0438 \u0430\u043D\u0430\u043B\u0438\u0442\u0438\u043A\u0443","html":'<ul>\n        <li>\u043D\u0430\u0436\u043C\u0438\u0442\u0435 \u043A\u043D\u043E\u043F\u043A\u0443 \xAB\u041D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438 cookies\xBB \u0432 \u0444\u0443\u0442\u0435\u0440\u0435 \u0441\u0430\u0439\u0442\u0430 \u0438 \u0432\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u0440\u0435\u0436\u0438\u043C \xAB\u0422\u043E\u043B\u044C\u043A\u043E \u043D\u0435\u043E\u0431\u0445\u043E\u0434\u0438\u043C\u044B\u0435\xBB;</li>\n        <li>\u043E\u0447\u0438\u0441\u0442\u0438\u0442\u0435 cookie \u0438 localStorage \u0434\u043B\u044F \u0434\u043E\u043C\u0435\u043D\u0430 \u0441\u0430\u0439\u0442\u0430 \u0432 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0430\u0445 \u0431\u0440\u0430\u0443\u0437\u0435\u0440\u0430;</li>\n        <li>\u043F\u0440\u0438 \u0436\u0435\u043B\u0430\u043D\u0438\u0438 \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u0443\u0439\u0442\u0435 \u0431\u043B\u043E\u043A\u0438\u0440\u043E\u0432\u0449\u0438\u043A \u042F\u043D\u0434\u0435\u043A\u0441 \u041C\u0435\u0442\u0440\u0438\u043A\u0438 \u0438\u043B\u0438 \u0430\u043D\u0430\u043B\u043E\u0433\u0438\u0447\u043D\u044B\u0435 \u0438\u043D\u0441\u0442\u0440\u0443\u043C\u0435\u043D\u0442\u044B \u0431\u0440\u0430\u0443\u0437\u0435\u0440\u0430.</li>\n      </ul>\n      <p class="legal-note">\n        \u041E\u0442\u043A\u043B\u044E\u0447\u0435\u043D\u0438\u0435 \u043E\u0431\u044F\u0437\u0430\u0442\u0435\u043B\u044C\u043D\u044B\u0445 cookie/localStorage \u043C\u043E\u0436\u0435\u0442 \u043F\u043E\u0432\u043B\u0438\u044F\u0442\u044C \u043D\u0430 \u044F\u0437\u044B\u043A \u0438\u043D\u0442\u0435\u0440\u0444\u0435\u0439\u0441\u0430, \u0441\u043E\u0445\u0440\u0430\u043D\u0435\u043D\u0438\u0435 \u0441\u043E\u0433\u043B\u0430\u0441\u0438\u044F \u0438\n        \u0440\u0430\u0431\u043E\u0442\u0443 \u0433\u043E\u043B\u043E\u0441\u043E\u0432\u0430\u043D\u0438\u044F.\n      </p>'},{"id":"section-8","title":"7. \u041F\u043E\u043B\u0435\u0437\u043D\u044B\u0435 \u0434\u043E\u043A\u0443\u043C\u0435\u043D\u0442\u044B","html":'<div class="legal-links-inline">\n        <a href="/privacy/">\u041F\u043E\u043B\u0438\u0442\u0438\u043A\u0430 \u043E\u0431\u0440\u0430\u0431\u043E\u0442\u043A\u0438 \u043F\u0435\u0440\u0441\u043E\u043D\u0430\u043B\u044C\u043D\u044B\u0445 \u0434\u0430\u043D\u043D\u044B\u0445</a>\n        <a href="https://yandex.com/support/metrica/ru/general/notification" target="_blank" rel="noopener noreferrer">\u0414\u043E\u043A\u0443\u043C\u0435\u043D\u0442\u0430\u0446\u0438\u044F \u042F\u043D\u0434\u0435\u043A\u0441 \u041C\u0435\u0442\u0440\u0438\u043A\u0438 \u043F\u043E \u0443\u0432\u0435\u0434\u043E\u043C\u043B\u0435\u043D\u0438\u044E \u043E \u0441\u0431\u043E\u0440\u0435 \u0441\u0442\u0430\u0442\u0438\u0441\u0442\u0438\u043A\u0438</a>\n        <a href="https://yandex.com/support/metrica/ru/general/cookie-usage" target="_blank" rel="noopener noreferrer">\u0414\u043E\u043A\u0443\u043C\u0435\u043D\u0442\u0430\u0446\u0438\u044F \u042F\u043D\u0434\u0435\u043A\u0441 \u041C\u0435\u0442\u0440\u0438\u043A\u0438 \u043F\u043E cookie</a>\n      </div>'},{"id":"section-9","title":"English Note","html":"<p>\n        This notice explains required browser storage, Yandex Metrica analytics, and the vote identifier used\n        for hourly race registration. Analytics loads only after consent. Google Analytics is not enabled as of\n        April 30, 2026.\n      </p>"}],"source":"/cookies/","official_language":"ru"}}};export{information_content_default as default};
